window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[301]={"id":"301","numero":301,"titre":"Tumeurs du côlon et du rectum","objectifs":[{"id":"301-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs colorectales se répartissent en <strong>tumeurs bénignes</strong> (polypes) et <strong>tumeurs malignes</strong> (adénocarcinomes +++). Toutes ne dégénèrent pas : seuls les <span class=\"kw-imagerie\">adénomes</span> et les <span class=\"kw-imagerie\">lésions festonnées</span> ont un potentiel de transformation maligne.</p>\n\n      <h5>Tumeurs bénignes — adénomes (polypes adénomateux)</h5>\n      <p><span class=\"kw-clinique\">Les</span> adénomes se développent à partir des <span class=\"kw-imagerie\">glandes de Lieberkühn</span> de la muqueuse colorectale. Toute <span class=\"kw-clinique\">lésion</span> adénomateuse est <span class=\"kw-def\">par définition une dysplasie</span>, qui peut être de <span class=\"kw-imagerie\">bas grade</span> ou de <span class=\"kw-imagerie\">haut grade</span> (l'adénome en dysplasie de haut <span class=\"kw-def\">grade</span> correspond au premier stade de cancer, le <span class=\"kw-imagerie\">carcinome in situ ou pTis</span>, sans franchissement de la lame basale). Ils représentent <span class=\"kw-chiffre\">~70 %</span> des polypes, avec une <span class=\"kw-def\">incidence</span> croissante avec l'<span class=\"kw-clinique\">âge</span> et une prédominance masculine (<span class=\"kw-chiffre\">2H / 1F</span>).</p>\n      <p><strong>Aspect macroscopique en <span class=\"kw-imagerie\">endoscopie</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Polype pédiculé</span> — <span class=\"kw-clinique\">lésion</span> exophytique rattachée à la paroi par un pied ± large.</li>\n        <li><span class=\"kw-imagerie\">Polype sessile</span> — large base d'implantation, épaisseur &gt; ½ du plus grand <span class=\"kw-clinique\">diamètre</span>.</li>\n        <li><span class=\"kw-imagerie\">Lésion plane (adénome plan)</span> — épaisseur &lt; ½ du plus grand <span class=\"kw-clinique\">diamètre</span>, <span class=\"kw-alerte\">plus à risque de cancérisation</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Classification</span> OMS — 3 sous-types histologiques d'adénome</strong> :</p>\n      <table >\n        <thead>\n          <tr><th>Sous-type</th><th>Fréquence</th><th>Risque de transformation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Adénome tubuleux</span></td><td><span class=\"kw-chiffre\">75 %</span></td><td>Faible</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Adénome tubulo-villeux</span></td><td><span class=\"kw-chiffre\">20 %</span></td><td>Intermédiaire</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Adénome villeux</span></td><td><span class=\"kw-chiffre\">5 %</span></td><td><span class=\"kw-alerte\">Élevé</span> (jusqu'à <span class=\"kw-chiffre\">40 %</span>), surtout si volumineux</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Tumeurs malignes — adénocarcinomes (ADK)</h5>\n      <p>L'immense majorité des cancers colorectaux sont des <span class=\"kw-def\">adénocarcinomes</span>. On distingue :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">ADK lieberkühnien</span> (+++) — forme habituelle, dérive des glandes de Lieberkühn.</li>\n        <li><span class=\"kw-imagerie\">ADK colloïde (mucineux)</span> — production importante de mucus, <span class=\"kw-def\">pronostic</span> plus défavorable.</li>\n        <li><span class=\"kw-imagerie\">ADK à cellules en bague à chaton</span> — forme rare, agressive.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Grade</span> de <span class=\"kw-bio\">différenciation</span> de l'ADK lieberkühnien</strong> (% de glandes coliques dans la tumeur) :</p>\n      <table >\n        <thead>\n          <tr><th>Grade</th><th>Description</th><th>% glandes coliques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Grade 1</span></td><td>Bien différencié</td><td><span class=\"kw-chiffre\">&gt; 95 %</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Grade 2</span></td><td>Moyennement différencié</td><td><span class=\"kw-chiffre\">50-95 %</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Grade 3</span></td><td>Peu différencié</td><td><span class=\"kw-chiffre\">5-50 %</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Grade 4</span></td><td>Indifférencié</td><td><span class=\"kw-chiffre\">&lt; 5 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres variétés histologiques rares</strong> : lymphomes malins non hodgkiniens, tumeurs stromales (GIST), tumeurs neuro-endocrines.</p>\n\n      <h5>Polypes qui ne dégénèrent jamais (à connaître pour ne pas paniquer)</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Polypes hyperplasiques</span> — très fréquents (<span class=\"kw-chiffre\">20-30 %</span> des sujets &gt;<span class=\"kw-chiffre\"> 50 ans</span>).</li>\n        <li><span class=\"kw-imagerie\">Polypes hamartomateux / juvéniles</span> — souvent pédiatriques.</li>\n        <li><span class=\"kw-imagerie\">Pseudo-polypes inflammatoires</span> — sur muqueuse de <span class=\"kw-clinique\">MICI</span> (mais la <span class=\"kw-clinique\">MICI</span> elle-même reste un FR de CCR).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Ne pas confondre polype hyperplasique (bénin pur) et <span class=\"kw-clinique\">lésion</span> festonnée (potentiel <span class=\"kw-etio\">néoplasique</span> réel) : la distinction est anatomopathologique et conditionne le rythme de <span class=\"kw-def\">surveillance</span>.</div>","frequence":0},{"id":"301-2","rang":"B","rubrique":"Étiologies","titre":"Connaître la liste des principales lésions coliques augmentant le risque de survenue ultérieure d’un cancer","contenu":"<p>Plusieurs lésions coliques préexistantes augmentent significativement le risque ultérieur de cancer colorectal (CCR). Leur identification conditionne la <span class=\"kw-imagerie\">surveillance endoscopique</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Mécanisme / <span class=\"kw-def\">critères de</span> risque</th><th>Conséquence pratique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Adénomes (polypes adénomateux)</span></td>\n            <td>\n              <strong>FR de cancérisation</strong> : taille <span class=\"kw-chiffre\">&gt; 1 cm</span> ; contingent <span class=\"kw-imagerie\">villeux &gt; 25 %</span> ; <span class=\"kw-imagerie\">dysplasie de haut grade</span> ; nombre <span class=\"kw-chiffre\">≥ 3</span>.<br>\n              <strong>Filiation</strong> : <span class=\"kw-chiffre\">60-80 %</span> des CCR dérivent d'un adénome ; <span class=\"kw-chiffre\">~5 %</span> des adénomes se transforment.\n            </td>\n            <td><span class=\"kw-imagerie\">Résection endoscopique</span> systématique + <span class=\"kw-def\">surveillance</span> adaptée au risque.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Lésions festonnées</span> (adénomes festonnés sessiles surtout)</td>\n            <td>Potentiel <span class=\"kw-etio\">néoplasique</span> distinct de la voie adénome-cancer, via la voie <span class=\"kw-bio\">CIMP+ / BRAF</span>.</td>\n            <td>Résection endoscopique ; <span class=\"kw-def\">surveillance</span> comme polype à risque si dysplasie ou <span class=\"kw-chiffre\">≥ 10 mm</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">MICI</span> (<span class=\"kw-clinique\">RCH</span>, maladie de Crohn colique)</td>\n            <td>\n              <strong>Critères à risque</strong> : durée <span class=\"kw-chiffre\">&gt; 8 ans</span> ; atteinte <span class=\"kw-chiffre\">&gt; 50 %</span> du côlon ;<br>\n              <strong>Association</strong> : <span class=\"kw-clinique\">cholangite sclérosante primitive</span> (<span class=\"kw-etio\">CSP</span>) → risque majoré.\n            </td>\n            <td><span class=\"kw-imagerie\">Coloscopie</span> de <span class=\"kw-def\">dépistage</span> débutée <span class=\"kw-chiffre\">6-8 ans</span> après le début des symptômes, rythme adapté au niveau de risque.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Acromégalie</span></td>\n            <td>Hyper-IGF-1 → effet mitogène sur l'épithélium colique, sur-risque de polypes.</td>\n            <td><span class=\"kw-imagerie\">Coloscopie</span> de <span class=\"kw-def\">dépistage</span> <span class=\"kw-imagerie\">dès le diagnostic d'acromégalie</span>.</td>\n          </tr>\n          <tr>\n            <td>ATCD personnel de <span class=\"kw-clinique\">CCR</span> ou d'<span class=\"kw-clinique\">adénome avancé</span></td>\n            <td>Récidive locale, <span class=\"kw-clinique\">lésion</span> synchrone ou métachrone (~<span class=\"kw-chiffre\">80 %</span> des récidives surviennent dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span>).</td>\n            <td><span class=\"kw-imagerie\">Coloscopie</span> de <span class=\"kw-def\">surveillance</span> post-résection (<span class=\"kw-chiffre\">1 / 3 / 5 ans</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Maladies génétiques prédisposantes (cf. obj-9 et obj-10)</h5>\n      <ul>\n        <li><span class=\"kw-def\">Syndrome de Lynch (HNPCC)</span> — <span class=\"kw-chiffre\">3-4 %</span> des CCR, mutation MMR (MLH1/MSH2/MSH6/PMS2), phénotype <span class=\"kw-bio\">MSI+ / dMMR</span>, polypes plans difficiles à voir.</li>\n        <li><span class=\"kw-def\">Polypose adénomateuse familiale (PAF)</span> — mutation <span class=\"kw-bio\">APC</span>, &gt; 100 polypes adénomateux, dégénérescence quasi-systématique &gt;<span class=\"kw-chiffre\"> 40 ans</span>.</li>\n        <li><span class=\"kw-def\">MAP</span> (autosomique récessive, gène <em>MUTYH</em>), <span class=\"kw-def\">Peutz-Jeghers</span> (<em>LKB1/STK11</em>), <span class=\"kw-def\">Cowden</span> (<em>PTEN</em>), <span class=\"kw-def\">polypose juvénile</span> (<em>SMAD4/BMPRA1</em>).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 La suspicion de polypose familiale repose sur <span class=\"kw-chiffre\">&gt; 10 polypes adénomateux colorectaux</span> synchrones ou métachrones → <strong>consultation d'oncogénétique</strong> + enquête familiale.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0},{"id":"301-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le vocabulaire permettant de comprendre un compte-rendu d’Anatomie et Cytologie Pathologique (ACP) de tumeur colo-rectale","contenu":"<p>Le compte-rendu ACP d'une tumeur colorectale est le <strong>document clé</strong> de la décision thérapeutique. Savoir le lire = savoir <span class=\"kw-imagerie\">stadifier</span>, <span class=\"kw-imagerie\">prognostiquer</span> et <span class=\"kw-imagerie\">poser l'indication de chimio adjuvante</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item du CR ACP</th><th>Définition / valeur attendue</th><th>Pertinence clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Type histologique</span></td>\n            <td>ADK lieberkühnien (+++), colloïde/mucineux, à cellules en bague à chaton.</td>\n            <td>Le type mucineux et celui à cellules en bague à chaton ont un <span class=\"kw-def\">pronostic</span> plus défavorable.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Grade de différenciation</span></td>\n            <td><span class=\"kw-def\">Grade</span> 1 (bien différencié, &gt; <span class=\"kw-chiffre\">95 %</span> glandes) à <span class=\"kw-chiffre\">Grade 4</span> (indifférencié, &lt; <span class=\"kw-chiffre\">5 %</span>).</td>\n            <td><span class=\"kw-def\">Grade</span> 3-4 = <span class=\"kw-alerte\">facteur de mauvais pronostic</span> (notamment au <span class=\"kw-def\">stade</span> II).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">pTNM</span> (<span class=\"kw-def\">classification</span> post-opératoire)</td>\n            <td>\n              <strong>pT</strong> : pTis (in situ, lame basale non franchie) ; pT1 (sous-muqueuse) ; pT2 (musculeuse) ; pT3 (sous-séreuse / mésorectum) ; pT4a (péritoine viscéral) ; pT4b (organe de voisinage).<br>\n              <strong>pN</strong> : pN0 / pN1 / pN2 selon nombre de ganglions envahis.<br>\n              <strong>pM</strong> : pM0 / pM1.\n            </td>\n            <td>Détermine le <span class=\"kw-def\">stade</span> (I à IV) et l'indication d'adjuvant.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Nombre de ganglions examinés</span></td>\n            <td><span class=\"kw-chiffre\">≥ 12 ganglions</span> recommandés sur la pièce opératoire.</td>\n            <td>Si &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>12</span> g</span>anglions au <span class=\"kw-def\">stade</span> II → <span class=\"kw-alerte\">facteur de mauvais pronostic</span> (sous-staging probable).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Engainements péri-nerveux</span></td>\n            <td><span class=\"kw-bio\">Envahissement</span> <span class=\"kw-etio\">tumoral</span> des espaces nerveux.</td>\n            <td>Facteur pronostique défavorable.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Emboles vasculaires (veineux / lymphatiques)</span></td>\n            <td>Cellules tumorales dans des vaisseaux.</td>\n            <td>Facteur de mauvais <span class=\"kw-def\">pronostic</span>, oriente la discussion d'adjuvant au <span class=\"kw-def\">stade</span> II.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Marges de résection</span></td>\n            <td>\n              <strong>R0</strong> : marges saines (<span class=\"kw-chiffre\">≥ 5 cm</span> côlon ; circonférentielle &gt; <span class=\"kw-chiffre\">1 mm</span> rectum) ;<br>\n              <strong>R1</strong> : <span class=\"kw-bio\">envahissement</span> microscopique ; <strong>R2</strong> : résidu macroscopique.\n            </td>\n            <td>R1/R2 = <span class=\"kw-alerte\">indication de reprise et/ou de RT-CT</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Statut MMR / MSI</span></td>\n            <td>\n              <strong>dMMR / MSI+</strong> : perte d'expression d'au moins 1 protéine MMR (MLH1, MSH2, MSH6, PMS2) en <span class=\"kw-bio\">IHC</span>, OU instabilité des microsatellites en <span class=\"kw-bio\">PCR</span>.<br>\n              <strong>pMMR / MSS</strong> : intégrité du système MMR.\n            </td>\n            <td>\n              dMMR/MSI+ = oriente vers <span class=\"kw-def\">Lynch</span> (si jeune ou ATCD familial) ; sensibilité à l'<span class=\"kw-ttt\">immunothérapie</span> au <span class=\"kw-def\">stade</span> métastatique ; <span class=\"kw-alerte\">bon pronostic</span> au <span class=\"kw-chiffre\">stade II</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Instabilité chromosomique (LOH+)</span></td>\n            <td><span class=\"kw-chiffre\">80-85 %</span> des CCR sporadiques — aneuploïdie, pertes alléliques.</td>\n            <td>Voie « classique » de carcinogenèse (côlon gauche le plus souvent).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Phénotype CIMP+</span></td>\n            <td><span class=\"kw-chiffre\">~20 %</span> des CCR — hyperméthylation des îlots CpG.</td>\n            <td>Associé aux lésions festonnées, mutations <span class=\"kw-bio\">BRAF</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Mutations RAS / BRAF</span> (au <span class=\"kw-def\">stade</span> métastatique)</td>\n            <td>Recherche somatique de <span class=\"kw-bio\">KRAS</span>, <span class=\"kw-bio\">NRAS</span>, <span class=\"kw-bio\">BRAF</span>.</td>\n            <td><span class=\"kw-ci\">Si KRAS/NRAS muté → anti-EGFR contre-indiqués</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 Au <span class=\"kw-def\">stade</span> II (T3-T4 N0 M0), <span class=\"kw-clinique\">les</span> facteurs ACP de mauvais <span class=\"kw-def\">pronostic</span> (T4, peu différencié, <span class=\"kw-bio\">emboles vasculaires</span>, engainements péri-nerveux, &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>12</span> g</span>anglions examinés, <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span>) justifient une discussion en <span class=\"kw-def\">RCP</span> de <span class=\"kw-ttt\">chimiothérapie</span> adjuvante.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — <span class=\"kw-bio\">Anatomopathologie</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/colorectal-cancer-1","label":"Radiopaedia : Colorectal cancer 1"},{"href":"https://radiopaedia.org/articles/rectal-cancer","label":"Radiopaedia : Rectal cancer"},{"href":"https://radiopaedia.org/articles/peritoneal-metastases","label":"Radiopaedia : Peritoneal metastases"},{"href":"https://radiopaedia.org/articles/familial-adenomatous-polyposis-1","label":"Radiopaedia : Familial adenomatous polyposis 1"},{"href":"https://radiopaedia.org/articles/hereditary-non-polyposis-colorectal-cancer-1?lang=us#:~:text=Hereditary%20non-polyposis%20colorectal%20cancer%20%28HNPCC%29%2C%20also%20known%20as,the%20most%20frequent%20form%20of%20hereditary%20colorectal%20cancer","label":"Hereditary non-polyposis colorectal cancer"},{"href":"https://radiopaedia.org/articles/rectum","label":"Radiopaedia : Rectum"},{"href":"https://radiopaedia.org/cases/normal-mri-pelvis-rectal-cancer-protocol?lang=us","label":"Radiopaedia : Normal mri pelvis rectal cancer protocol"},{"href":"https://cerf.radiologie.fr/sites/cerf.radiologie.fr/files/files/enseignement/pdf/2.2%20FP%20Radio%20anatomie%20du%20rectum.pdf","label":"2.2 fp radio anatomie du rectum"}]},{"id":"301-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition des polypes et des polyposes","contenu":"<p><span class=\"kw-clinique\">Les</span> définitions de polype et de polypose sont <strong>indispensables</strong> pour comprendre le risque de CCR et organiser la <span class=\"kw-def\">surveillance</span>.</p>\n\n      <h5>Polype — définition</h5>\n      <p>Un <span class=\"kw-def\">polype</span> est une <strong><span class=\"kw-clinique\">lésion</span> saillante macroscopique de la muqueuse</strong> à la surface du tube digestif. La définition est purement <strong>morphologique</strong> ; elle ne préjuge pas du type histologique (adénomateux, hyperplasique, hamartomateux, <span class=\"kw-etio\">inflammatoire</span>…) ni du potentiel évolutif.</p>\n      <p><strong>Aspect macroscopique en <span class=\"kw-imagerie\">endoscopie</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Polype pédiculé</span> — rattaché à la paroi colique par un pied ± large, exophytique.</li>\n        <li><span class=\"kw-imagerie\">Polype sessile</span> — base d'implantation large, épaisseur <span class=\"kw-chiffre\">&gt; ½</span> du plus grand <span class=\"kw-clinique\">diamètre</span>.</li>\n        <li><span class=\"kw-imagerie\">Lésion plane (polype plan)</span> — épaisseur <span class=\"kw-chiffre\">&lt; ½</span> du plus grand <span class=\"kw-clinique\">diamètre</span>, <span class=\"kw-alerte\">plus à risque de cancérisation</span> et plus difficile à voir en <span class=\"kw-imagerie\">coloscopie</span>.</li>\n      </ul>\n\n      <h5>Dysplasie / néoplasie intra-épithéliale</h5>\n      <p>Tout <span class=\"kw-imagerie\">adénome</span> est <strong>par définition une dysplasie</strong>. On distingue :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Dysplasie de bas grade</span> — anomalies cytologiques modérées.</li>\n        <li><span class=\"kw-imagerie\">Dysplasie de haut grade / carcinome in situ / pTis</span> — anomalies sévères <strong>sans franchissement de la lame basale</strong>.</li>\n        <li>Franchissement de la lame basale = <span class=\"kw-alerte\">cancer invasif T1</span>.</li>\n      </ul>\n\n      <h5>Polypose — définition</h5>\n      <p>Une <span class=\"kw-def\">polypose</span> est définie par la présence d'un <strong>grand nombre de polypes</strong> synchrones ou métachrones du tube digestif. En pratique, on évoque une polypose familiale dès <span class=\"kw-chiffre\">&gt; 10 polypes adénomateux colorectaux</span> (synchrones ou métachrones), d'autant plus s'il existe des ATCD personnels ou familiaux de CCR. Toute suspicion de polypose impose une <strong>consultation d'oncogénétique avec enquête familiale</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Polypose</th><th>Gène</th><th>Transmission</th><th>Type de polypes</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">PAF</span> (polypose adénomateuse familiale)</td><td><span class=\"kw-bio\">APC</span> (5q21)</td><td>Autosomique <strong>dominante</strong></td><td>Adénomateux (&gt; 100)</td></tr>\n          <tr><td><span class=\"kw-def\">MAP</span> (MYH-associated polyposis)</td><td><span class=\"kw-bio\">MUTYH</span></td><td>Autosomique <strong>récessive</strong></td><td>Adénomateux (5-100, plus tardifs)</td></tr>\n          <tr><td><span class=\"kw-def\">Peutz-Jeghers</span></td><td><span class=\"kw-bio\">LKB1 / STK11</span></td><td>Autosomique dominante</td><td>Hamartomateux + <span class=\"kw-clinique\">lentiginose péri-orificielle</span></td></tr>\n          <tr><td><span class=\"kw-def\">Cowden</span></td><td><span class=\"kw-bio\">PTEN</span></td><td>Autosomique dominante</td><td>Hamartomes (peau, thyroïde, côlon, endomètre)</td></tr>\n          <tr><td><span class=\"kw-def\">Polypose juvénile</span></td><td><span class=\"kw-bio\">SMAD4 / BMPRA1</span></td><td>Autosomique dominante</td><td>Hamartomes diffus du tube digestif</td></tr>\n          <tr><td><span class=\"kw-def\">Polypose hyperplasique / festonnée</span></td><td>Non identifié</td><td>—</td><td>Hyperplasiques / festonnés (risque variable selon contingent adénomateux)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 Une polypose <strong>n'est pas synonyme</strong> de polypose adénomateuse familiale (PAF). Il existe des polyposes hamartomateuses, hyperplasiques et mixtes, dont le risque de CCR varie de modéré (<span class=\"kw-chiffre\">20-40 %</span>) à très élevé (PAF : <span class=\"kw-chiffre\">100 %</span> si non traité).</div>","frequence":0},{"id":"301-5","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître la filiation adénome cancer","contenu":"<div class=\"callout callout-warn\">⚠️ <strong>Sujet tombé en annale EDN.</strong> Bien maîtriser : (1) la proportion de CCR issus d'un adénome (<span class=\"kw-chiffre\">60-80 %</span>) ; (2) la durée moyenne de la filiation (<span class=\"kw-chiffre\">10-15 ans</span> dysplasie bas <span class=\"kw-def\">grade</span> → <span class=\"kw-clinique\">carcinome</span> in situ) ; (3) la séquence cytologique (BG → HG → in situ → T1 invasif).</div>\n\n      <h5>Filiation adénome → <span class=\"kw-clinique\">carcinome</span> — séquence et chiffres clés</h5>\n      <p>La <span class=\"kw-def\">filiation adénome-cancer</span> est la voie principale de cancérogenèse colorectale. Elle représente <span class=\"kw-chiffre\">60-80 %</span> (parfois cités <span class=\"kw-chiffre\">60-90 %</span>) des cancers colorectaux sporadiques. Seulement <span class=\"kw-chiffre\">~5 %</span> des adénomes vont effectivement se transformer.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Anomalie histologique</th><th>Franchissement de la lame basale</th><th><span class=\"kw-def\">Stade</span> TNM</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>1</td><td><span class=\"kw-imagerie\">Muqueuse normale</span></td><td>—</td><td>—</td></tr>\n          <tr><td>2</td><td><span class=\"kw-imagerie\">Adénome en dysplasie de bas grade</span></td><td>Non</td><td>—</td></tr>\n          <tr><td>3</td><td><span class=\"kw-imagerie\">Adénome en dysplasie de haut grade / carcinome in situ</span></td><td>Non</td><td><span class=\"kw-imagerie\">pTis</span></td></tr>\n          <tr><td>4</td><td><span class=\"kw-alerte\">Cancer invasif sous-muqueux</span></td><td><strong>Oui</strong></td><td><span class=\"kw-imagerie\">T1</span></td></tr>\n          <tr><td>5</td><td>Atteinte de la <span class=\"kw-imagerie\">musculeuse</span></td><td>—</td><td><span class=\"kw-imagerie\">T2</span></td></tr>\n          <tr><td>6</td><td>Sous-séreuse / <span class=\"kw-imagerie\">mésorectum</span></td><td>—</td><td><span class=\"kw-imagerie\">T3</span></td></tr>\n          <tr><td>7</td><td><span class=\"kw-imagerie\">Péritoine viscéral (T4a)</span> / <span class=\"kw-imagerie\">organe de voisinage (T4b)</span></td><td>—</td><td><span class=\"kw-imagerie\">T4a / T4b</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Durée moyenne</strong> : <span class=\"kw-chiffre\">10 à 15 ans</span> entre une dysplasie de bas <span class=\"kw-def\">grade</span> et le stade de <span class=\"kw-clinique\">carcinome</span> in situ. Cette latence longue justifie l'efficacité du <span class=\"kw-imagerie\">dépistage organisé</span> par iFOBT et la <span class=\"kw-imagerie\">résection endoscopique</span> systématique de tout polype identifié.</p>\n\n      <h5>Facteurs de cancérisation d'un adénome</h5>\n      <ul>\n        <li>Taille <span class=\"kw-chiffre\">&gt; 1 cm</span>.</li>\n        <li>Contingent <span class=\"kw-imagerie\">villeux &gt; 25 %</span>.</li>\n        <li><span class=\"kw-imagerie\">Dysplasie de haut grade</span> (pTis).</li>\n        <li>Nombre <span class=\"kw-chiffre\">≥ 3</span> adénomes synchrones.</li>\n      </ul>\n\n      <h5>Voies moléculaires (rappel)</h5>\n      <p>3 mécanismes de carcinogenèse coexistent :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Instabilité chromosomique (LOH+)</span> — <span class=\"kw-chiffre\">80-85 %</span> des CCR sporadiques, voie APC → KRAS → p53, côlon gauche +++.</li>\n        <li><span class=\"kw-bio\">Instabilité génétique (MSI+ / RER+ / dMMR)</span> — <span class=\"kw-chiffre\">~15 %</span>, hyperméthylation biallélique de MLH1 chez le sujet âgé (sporadique) OU mutation MMR constitutionnelle (Lynch), côlon droit, femme &gt;<span class=\"kw-chiffre\"> 60 ans</span>.</li>\n        <li><span class=\"kw-bio\">Phénotype méthylateur (CIMP+)</span> — <span class=\"kw-chiffre\">~20 %</span>, hyperméthylation des îlots CpG des promoteurs.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 Le franchissement de la <span class=\"kw-imagerie\">lame basale</span> est <strong>le pivot conceptuel</strong> : avant = <span class=\"kw-clinique\">lésion</span> intra-épithéliale (résection endoscopique suffisante si R0) ; après = cancer invasif T1 (discussion en <span class=\"kw-def\">RCP</span>, parfois résection endoscopique seule si T1 superficiel R0, sinon <span class=\"kw-ttt\">chirurgie</span>).</div>","frequence":0},{"id":"301-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découverte","contenu":"<p>Le cancer colorectal peut être révélé dans <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>randes circonstances</strong>. Aucune n'est spécifique ; toute symptomatologie digestive récente chez un adulte <span class=\"kw-chiffre\">≥ 50 ans</span> doit faire évoquer le diagnostic.</p>\n\n      <table >\n        <thead>\n          <tr><th>Circonstance</th><th>Manifestations à connaître</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Dépistage organisé</span></td>\n            <td>\n              <strong>Asymptomatique</strong> : <span class=\"kw-bio\">iFOBT positif</span> (population générale,<span class=\"kw-chiffre\"> 50-74 ans</span>, tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span>) ;<br>\n              <strong><span class=\"kw-imagerie\">Coloscopie</span></strong> : indiquée systématiquement si iFOBT+ (positif dans <span class=\"kw-chiffre\">4-5 %</span> des cas).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Saignements digestifs</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Rectorragies</span></strong> ++ : côlon gauche, peu abondantes, récidivantes ;<br>\n              <strong><span class=\"kw-clinique\">Méléna</span></strong> : côlon droit, en amont de l'angle colique droit ;<br>\n              <strong>Saignement occulte</strong> : <span class=\"kw-bio\">anémie ferriprive</span> chronique, surtout côlon droit.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Troubles du transit récents</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Constipation</span></strong> d'apparition progressive ;<br>\n              <strong><span class=\"kw-clinique\">Diarrhée</span></strong> ou <strong>alternance diarrhée-constipation</strong> ;<br>\n              <strong>Modification d'une symptomatologie digestive ancienne</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleurs abdominales</span></td>\n            <td>\n              <strong>Douleurs coliques</strong> mal systématisées, <span class=\"kw-clinique\">pesanteur</span>, ballonnement ;<br>\n              <strong><span class=\"kw-clinique\">Syndrome de Koenig</span></strong> (rare) : crises douloureuses brutales + borborygmes + ondulations péristaltiques, cédant en débâcle diarrhéique → témoigne d'une <span class=\"kw-alerte\">sténose tumorale serrée</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Signes généraux</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">AEG</span></strong> : <span class=\"kw-clinique\">asthénie</span>, anorexie, <span class=\"kw-clinique\">amaigrissement</span> ; parfois fièvre.<br>\n              <strong>Anémie ferriprive</strong> isolée : circonstance fréquente, doit toujours faire chercher une cause digestive.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Complications révélatrices</span></td>\n            <td>\n              <strong>Occlusion</strong> : côlon gauche dans <span class=\"kw-chiffre\">70 %</span> des cas (selles solides, <span class=\"kw-clinique\">masse</span> sténosante en virole) ;<br>\n              <strong>Perforation</strong> ou <strong><span class=\"kw-clinique\">péritonite</span></strong> ;<br>\n              <strong><span class=\"kw-clinique\">Fistule</span></strong> ;<br>\n              <strong>Infections à <span class=\"kw-clinique\">porte d'entrée</span> digestive</strong> : <span class=\"kw-clinique\">endocardite</span>, s<span class=\"kw-chiffre\">igm</span>oïdite, <span class=\"kw-clinique\">abcès</span> hépatique.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Découverte métastatique</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Hépatomégalie</span> hétérogène</strong> ou « foie marronné » ;<br>\n              <strong><span class=\"kw-clinique\">Dyspnée</span></strong> sur M+ pulmonaires ;<br>\n              <strong>Carcinose péritonéale</strong> : <span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">nodule</span> de Sœur Marie-Joseph ;<br>\n              <span class=\"kw-clinique\">Adénopathie sus-claviculaire gauche de Troisier</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>À l'examen clinique systématique</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Masse abdominale</span> palpable d'origine colique (plus fréquente au côlon droit, plus grand <span class=\"kw-clinique\">diamètre</span>).</li>\n        <li>Signes de <span class=\"kw-alerte\">carcinose péritonéale</span> : <span class=\"kw-clinique\">ascite</span>, gâteau épiploïque, <span class=\"kw-clinique\">nodule</span> ombilical.</li>\n        <li><span class=\"kw-clinique\">Adénopathie sus-claviculaire gauche</span> (Troisier).</li>\n        <li><span class=\"kw-imagerie\">Toucher rectal</span> systématique : recherche d'un cancer du rectum synchrone, sang au TR, carcinose dans le cul-de-sac de Douglas.</li>\n        <li>Métastases : <span class=\"kw-imagerie\">hépatomégalie hétérogène</span>, signes pulmonaires, douleurs osseuses.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ Une <span class=\"kw-bio\">anémie ferriprive</span> chez un sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> est un <span class=\"kw-alerte\">cancer du côlon droit jusqu'à preuve du contraire</span> → <span class=\"kw-imagerie\">coloscopie</span> totale + biopsies systématique.</div>","frequence":3},{"id":"301-7","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le rythme de surveillance en fonction du nombre et de la taille des adénomes","contenu":"<p>Après résection endoscopique d'un polype à risque de dégénérescence (adénome ou polype festonné), la <strong>cadence de la <span class=\"kw-imagerie\">coloscopie</span> suivante</strong> dépend de 3 paramètres : <span class=\"kw-imagerie\">nombre</span>, <span class=\"kw-imagerie\">taille</span> et <span class=\"kw-imagerie\">grade de dysplasie</span> du / des polypes retirés.</p>\n\n      <table >\n        <thead>\n          <tr><th>Niveau de risque</th><th>Nombre</th><th>Taille</th><th><span class=\"kw-def\">Grade</span> / dysplasie</th><th><span class=\"kw-imagerie\">Coloscopie</span> de contrôle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Polype bas risque</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 3</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 10 mm</span></td>\n            <td>\n              <strong>Adénome</strong> : dysplasie de bas <span class=\"kw-def\">grade</span> ;<br>\n              <strong>Polype festonné</strong> : absence de dysplasie.\n            </td>\n            <td>À <span class=\"kw-chiffre\">5 ans</span>, puis <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">3-5-10 ans</span> selon résultats.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Polype haut risque</span></td>\n            <td><span class=\"kw-chiffre\">≥ 3</span></td>\n            <td><span class=\"kw-chiffre\">≥ 10 mm</span></td>\n            <td>\n              <strong>Adénome</strong> : dysplasie de haut <span class=\"kw-def\">grade</span> ou contingent villeux ;<br>\n              <strong>Polype festonné</strong> : dysplasie présente.\n            </td>\n            <td>À <span class=\"kw-chiffre\">3 ans</span>, puis <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">3-5 ans</span> selon résultats.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Cas particulier — résection incomplète ou de mauvaise qualité</h5>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Coloscopie</span> pré-opératoire incomplète</strong> (mauvaise préparation, <span class=\"kw-clinique\">lésion</span> infranchissable) → <span class=\"kw-imagerie\">nouvelle coloscopie dans les 6 mois</span> post-opératoires.</li>\n        <li><strong>Polype non résécable in toto</strong> (nappe villeuse, adénome villeux étendu) → discussion en <span class=\"kw-def\">RCP</span>, <span class=\"kw-ttt\">chirurgie</span> segmentaire à envisager.</li>\n        <li><strong>Résection R1</strong> → 1ʳᵉ intention : nouvelle <span class=\"kw-imagerie\">endoscopie</span> pour élargir ; 2ⁿᵈ intention : <span class=\"kw-ttt\">chirurgie</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> 3 premières coloscopies de <span class=\"kw-def\">surveillance</span> suivent une cadence soutenue (<span class=\"kw-chiffre\">1-3 ans</span>) ; à partir de la 3ᵉ <span class=\"kw-imagerie\">coloscopie</span> normale, le rythme peut être espacé (sauf prédisposition <span class=\"kw-etio\">génétique</span>).</div>\n\n      <div class=\"callout callout-warn\">⚠️ Ne pas confondre <strong><span class=\"kw-def\">surveillance</span> post-polypectomie</strong> (sujet asymptomatique, polype enlevé) avec <strong>surveillance post-CCR opéré</strong> (cf. surveillance carcinologique : clinique + écho AP + <span class=\"kw-imagerie\">RXT</span>, cadencées différemment).</div>","frequence":0},{"id":"301-8","rang":"B","rubrique":"Épidémiologie","titre":"Épidémiologie descriptive : connaître l’incidence et la prévalence du cancer du rectum","contenu":"<p><span class=\"kw-clinique\">Les</span> cancers du côlon et du rectum (CCR) sont l'<strong>une des grandes causes de cancer en France</strong>. Bien retenir les chiffres bruts et la tendance évolutive (<span class=\"kw-def\">incidence</span> et mortalité <span class=\"kw-imagerie\">en diminution</span> grâce au <span class=\"kw-def\">dépistage</span> organisé et à la résection des lésions précancéreuses).</p>\n\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th><th>Commentaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Rang d'<span class=\"kw-def\">incidence</span></strong></td>\n            <td><span class=\"kw-chiffre\">2ᵉ</span> cancer de la femme (après sein) ; <span class=\"kw-chiffre\">3ᵉ</span> de l'homme (après prostate et poumon) ; <span class=\"kw-chiffre\">3ᵉ-4ᵉ</span> tous sexes confondus.</td>\n            <td><span class=\"kw-def\">Incidence</span> en diminution (<span class=\"kw-chiffre\">−0,6 %/an</span> en moyenne entre 1990 et 2018).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> en France (2017)</strong></td>\n            <td>≈ <span class=\"kw-chiffre\">418 500</span> personnes vivantes.</td>\n            <td>~<span class=\"kw-chiffre\">5 %</span> de la population française aura un CCR dans sa vie.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> en France (2018)</strong></td>\n            <td><span class=\"kw-chiffre\">43 300</span> nouveaux cas/an (<span class=\"kw-chiffre\">11 %</span> des nouveaux cas de cancer).</td>\n            <td>Légère prédominance masculine (~23 200 hommes).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span> en France</strong></td>\n            <td><span class=\"kw-chiffre\">17 100</span> décès/an = <span class=\"kw-chiffre\">2ᵉ cause de mortalité par cancer</span> (après le poumon), soit <span class=\"kw-chiffre\">12 %</span> de la <span class=\"kw-def\">mortalité</span> par cancer.</td>\n            <td><span class=\"kw-def\">Mortalité</span> en diminution (<span class=\"kw-chiffre\">−1,6 %/an</span> entre 1990 et 2018).</td>\n          </tr>\n          <tr>\n            <td><strong>Survie à<span class=\"kw-chiffre\"> 5 ans</span> (tous stades)</strong></td>\n            <td><span class=\"kw-chiffre\">~63-65 %</span>.</td>\n            <td><span class=\"kw-def\">Stade</span> I : <span class=\"kw-chiffre\">94 %</span> ; <span class=\"kw-chiffre\">Stade II</span> : <span class=\"kw-chiffre\">80 %</span> ; <span class=\"kw-chiffre\">Stade III</span> : <span class=\"kw-chiffre\">45-60 %</span> ; <span class=\"kw-chiffre\">Stade IV</span> : <span class=\"kw-chiffre\">10 %</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Localisations</strong></td>\n            <td>\n              <strong>Côlon</strong> : <span class=\"kw-chiffre\">65 %</span> des CCR (2/3) — côlon <span class=\"kw-chiffre\">gauche</span> dans <span class=\"kw-chiffre\">2/3</span> des cas (s<span class=\"kw-chiffre\">igm</span>oïde +++), côlon droit dans <span class=\"kw-chiffre\">1/3</span> ;<br>\n              <strong>Rectum</strong> : <span class=\"kw-chiffre\">35 %</span> des CCR (extrémité distale à <span class=\"kw-chiffre\">≤ 15 cm</span> de la marge anale en <span class=\"kw-imagerie\">rectoscopie</span> rigide).\n            </td>\n            <td>Cancers du rectum : prédominance masculine marquée (<span class=\"kw-chiffre\">2H / 1F</span>) ; cancers du côlon : <span class=\"kw-chiffre\">1H / 1F</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Âge médian au diagnostic</strong></td>\n            <td>Homme : <span class=\"kw-chiffre\">71 ans</span> ; femme : <span class=\"kw-chiffre\">73 ans</span>.</td>\n            <td><span class=\"kw-chiffre\">~10 %</span> des CCR sont identifiés avant <span class=\"kw-chiffre\">50 ans</span> (justifie l'attention aux signes d'alerte chez le sujet jeune).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Survie selon le <span class=\"kw-def\">stade</span> TNM</h5>\n      <ul>\n        <li><strong><span class=\"kw-def\">Stade</span> I</strong> (T1-T2 N0 M0) : survie à<span class=\"kw-chiffre\"> 5 ans</span> <span class=\"kw-chiffre\">~94 %</span>.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> II</strong> (T3-T4 N0 M0) : <span class=\"kw-chiffre\">~80 %</span> après <span class=\"kw-ttt\">chirurgie</span> seule.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> III</strong> (N+) : <span class=\"kw-chiffre\">45-60 %</span> après <span class=\"kw-ttt\">chirurgie</span> seule ; <span class=\"kw-chiffre\">~75 %</span> après chirurgie + chimio adjuvante.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> IV</strong> (M+) : <span class=\"kw-chiffre\">~10 %</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 Particularité du <strong>rectum</strong> : <span class=\"kw-clinique\">les</span> veines rectales moyennes et inférieures drainent dans le <strong>système cave</strong>, ce qui explique la possibilité d'une <span class=\"kw-alerte\">métastase pulmonaire isolée sans atteinte hépatique</span> dans certains cancers du bas / moyen rectum.</div>","frequence":3},{"id":"301-9","rang":"A","rubrique":"Étiologies","titre":"Épidémiologie analytique : connaître les facteurs de risque","contenu":"<p>L'<span class=\"kw-def\">épidémiologie</span> analytique du CCR distingue 3 <strong>niveaux de risque</strong> qui conditionnent la stratégie de <span class=\"kw-def\">dépistage</span>. Sujet à très haute valeur d'annale.</p>\n\n      <h5><span class=\"kw-clinique\">Les</span> 3 niveaux de risque</h5>\n      <table >\n        <thead>\n          <tr><th>Niveau</th><th>%</th><th>Qui est concerné ?</th><th>Stratégie de <span class=\"kw-def\">dépistage</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Modéré</td>\n            <td><span class=\"kw-chiffre\">80 %</span></td>\n            <td>Population générale, <span class=\"kw-chiffre\">≥ 50 ans</span>, sans histoire familiale, sans ATCD personnel d'adénome ou de CCR.</td>\n            <td><span class=\"kw-def\">Dépistage</span> <strong>organisé</strong> par <span class=\"kw-bio\">iFOBT</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span>,<span class=\"kw-chiffre\"> 50-74 ans</span>.</td>\n          </tr>\n          <tr>\n            <td>Élevé (RR 4-10)</td>\n            <td><span class=\"kw-chiffre\">15 %</span></td>\n            <td>\n              <strong>ATCD personnels</strong> : polype adénomateux, polype festonné, CCR ;<br>\n              <strong>ATCD familiaux 1ᵉʳ degré</strong> : CCR ou adénome ;<br>\n              <strong><span class=\"kw-chiffre\">≥ 2</span> ATCD du même côté généalogique au 2ᵉ-3ᵉ degré</strong> ;<br>\n              <strong>Acromégalie</strong> ;<br>\n              <strong><span class=\"kw-clinique\">MICI</span></strong> : &gt;<span class=\"kw-chiffre\"> 8 ans</span> d'<span class=\"kw-clinique\">évolution</span>, cholangite sclérosante associée, &gt; <span class=\"kw-chiffre\">50 %</span> du côlon atteint.\n            </td>\n            <td><span class=\"kw-imagerie\">Coloscopie</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 ans</span> ; <span class=\"kw-ci\">pas de test immunologique</span>.</td>\n          </tr>\n          <tr>\n            <td>Très élevé</td>\n            <td><span class=\"kw-chiffre\">5 %</span></td>\n            <td>ATCD familiaux de <span class=\"kw-def\">PAF</span>, <span class=\"kw-def\">syndrome HNPCC (Lynch)</span> ou autres polyposes.</td>\n            <td>Programme spécifique après <strong>consultation d'oncogénétique</strong> : <span class=\"kw-imagerie\">coloscopie</span> 1×/an ou tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> ± <span class=\"kw-ttt\">chirurgie</span> prophylactique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Formes familiales <span class=\"kw-bio\">vs</span> sporadiques</h5>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Formes familiales avec anomalie identifiée</strong> (<span class=\"kw-chiffre\">~5 %</span>)</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Syndrome de Lynch</span></strong> : <span class=\"kw-chiffre\">3-4 %</span> des CCR ;<br>\n              <strong>Polyposes familiales</strong> : PAF, MAP, Cowden, Peutz-Jeghers, polypose juvénile.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Formes familiales sans anomalie identifiée</strong> (<span class=\"kw-chiffre\">~10 %</span>)</td>\n            <td>ATCD familial de CCR ou d'adénome &gt; <span class=\"kw-chiffre\">1 cm</span> ou villeux dans la fratrie / <span class=\"kw-clinique\">les</span> enfants.</td>\n          </tr>\n          <tr>\n            <td><strong>CCR sporadique</strong> (<span class=\"kw-chiffre\">~85 %</span>)</td>\n            <td>\n              <strong>Âge &gt;<span class=\"kw-chiffre\"> 50 ans</span></strong> = principal FR (<span class=\"kw-chiffre\">90 %</span> des CCR) ;<br>\n              <strong>ATCD personnels</strong> : adénome, polype festonné, CCR ; <span class=\"kw-clinique\">MICI</span> ; acromégalie ; <span class=\"kw-etio\">diabète</span> / insulinorésistance ;<br>\n              <strong>Mode de vie</strong> : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span>, surpoids / <span class=\"kw-etio\">obésité</span> / sédentarité, viande rouge et charcuterie, alimentation pauvre en fibres ;<br>\n              <strong>Facteurs protecteurs</strong> : activité physique régulière, alimentation riche en fibres, <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span> au long cours, THM, contraception œstro-progestative, <span class=\"kw-clinique\">polyarthrite rhumatoïde</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Modalités de <span class=\"kw-def\">surveillance</span> endoscopique par groupe à risque</h5>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Début de la surveillance</th><th>Rythme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Population générale (<span class=\"kw-chiffre\">≥ 50 ans</span>, sans ATCD)</td>\n            <td>À partir de <span class=\"kw-chiffre\">50 ans</span></td>\n            <td>iFOBT tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> ; si <span class=\"kw-imagerie\">coloscopie</span> normale, <span class=\"kw-chiffre\">tous les 5 ans</span>.</td>\n          </tr>\n          <tr>\n            <td>ATCD familial de CCR au 1ᵉʳ degré</td>\n            <td>À <span class=\"kw-chiffre\">45 ans</span> ou <span class=\"kw-chiffre\">10 ans</span> avant l'âge du cas index</td>\n            <td>Contrôle à <span class=\"kw-chiffre\">5 ans</span>.</td>\n          </tr>\n          <tr>\n            <td>ATCD familial d'adénome avancé (&gt; <span class=\"kw-chiffre\">1 cm</span>) au 1ᵉʳ degré</td>\n            <td>À <span class=\"kw-chiffre\">45 ans</span> ou <span class=\"kw-chiffre\">10 ans</span> avant l'âge du cas index</td>\n            <td>Selon résultat de la 1ʳᵉ <span class=\"kw-imagerie\">coloscopie</span>.</td>\n          </tr>\n          <tr>\n            <td>ATCD personnel de CCR après <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-imagerie\">coloscopie</span> préop <strong>incomplète</strong></td>\n            <td>—</td>\n            <td>À <span class=\"kw-chiffre\">6 mois</span>, puis <span class=\"kw-chiffre\">3 ans</span>, puis <span class=\"kw-chiffre\">5 ans</span>.</td>\n          </tr>\n          <tr>\n            <td>ATCD personnel de CCR après <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-imagerie\">coloscopie</span> préop <strong>complète</strong></td>\n            <td>—</td>\n            <td>À <span class=\"kw-chiffre\">1 an</span>, puis <span class=\"kw-chiffre\">3 ans</span>, puis <span class=\"kw-chiffre\">5 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">RCH</span> ou <span class=\"kw-clinique\">maladie de Crohn</span></td>\n            <td><span class=\"kw-chiffre\">6-8 ans</span> après le début des symptômes</td>\n            <td>Adaptée au niveau de risque (extension, cholangite sclérosante).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Acromégalie</span></td>\n            <td>Dès le diagnostic d'acromégalie</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>iFOBT</strong> (immunological Fecal Occult Blood Test) : sensibilité <span class=\"kw-chiffre\">~80 %</span>, plus sensible que l'Hemoccult mais moins spécifique. Positif dans <span class=\"kw-chiffre\">4-5 %</span> des cas → <span class=\"kw-imagerie\">coloscopie</span> systématique. Le taux de participation reste faible en France (<span class=\"kw-chiffre\">~30 %</span>).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":3},{"id":"301-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître l’indication d’un test génétique","contenu":"<p>La recherche d'un <span class=\"kw-clinique\">syndrome de prédisposition</span> <span class=\"kw-etio\">héréditaire</span> (<span class=\"kw-def\">Lynch</span>, <span class=\"kw-def\">PAF</span>) repose sur 3 étapes : suspicion clinique → analyse de la tumeur (<span class=\"kw-bio\">IHC</span>, MSI) → consultation d'oncogénétique + séquençage constitutionnel.</p>\n\n      <h5>Indications de la recherche du phénotype MMR / MSI sur la tumeur</h5>\n      <p>L'<span class=\"kw-imagerie\">immunohistochimie (IHC)</span> des 4 protéines MMR (<span class=\"kw-bio\">MLH1</span>, <span class=\"kw-bio\">MSH2</span>, <span class=\"kw-bio\">MSH6</span>, <span class=\"kw-bio\">PMS2</span>) et l'<span class=\"kw-imagerie\">analyse MSI par PCR</span> sont indiquées sur la pièce opératoire (ou la <span class=\"kw-ttt\">biopsie</span>) en cas de :</p>\n      <ul>\n        <li>Patient avec CCR de <span class=\"kw-chiffre\">&lt; 70 ans</span>.</li>\n        <li>Patient avec CCR + ATCD familial au 1ᵉʳ degré d'un cancer du spectre du Lynch.</li>\n        <li>Indication large = systématique sur <strong>tout cancer du rectum</strong> avant <span class=\"kw-chiffre\">60 ans</span>.</li>\n      </ul>\n      <p>L'<span class=\"kw-bio\">IHC</span> peut montrer une <span class=\"kw-imagerie\">perte d'expression</span> d'une ou plusieurs protéines MMR, orientant le séquençage constitutionnel vers le gène impliqué.</p>\n\n      <h5><span class=\"kw-def\">Critères cliniques</span> de suspicion d'un <span class=\"kw-clinique\">syndrome de Lynch</span></h5>\n      <table >\n        <thead>\n          <tr><th>Critères d'Amsterdam II</th><th><span class=\"kw-def\">Critères de</span> Bethesda révisés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong><span class=\"kw-clinique\">Les</span> 4 critères doivent être réunis :</strong>\n              <ul>\n                <li><span class=\"kw-chiffre\">≥ 3</span> sujets atteints de cancer du spectre HNPCC <strong>étroit</strong>.</li>\n                <li><span class=\"kw-chiffre\">≥ 1</span> apparenté au 1ᵉʳ degré des 2 autres.</li>\n                <li><span class=\"kw-chiffre\">≥ 2</span> générations successives concernées.</li>\n                <li><span class=\"kw-chiffre\">≥ 1</span> cas diagnostiqué <span class=\"kw-chiffre\">avant 50 ans</span>.</li>\n                <li>Exclusion d'une polypose adénomateuse familiale.</li>\n              </ul>\n            </td>\n            <td>\n              <strong>Au moins 1 critère parmi :</strong>\n              <ul>\n                <li>CCR diagnostiqué <span class=\"kw-chiffre\">avant 50 ans</span>.</li>\n                <li>CCR avec <span class=\"kw-bio\">MSI+ / dMMR</span> en <span class=\"kw-bio\">IHC</span> <span class=\"kw-chiffre\">avant 60 ans</span>.</li>\n                <li>2 cancers synchrones ou métachrones du spectre HNPCC large, quel que soit l'âge.</li>\n                <li>CCR + <span class=\"kw-chiffre\">≥ 2</span> apparentés du 1ᵉʳ-2ᵉ degré avec un cancer du spectre HNPCC large.</li>\n                <li>CCR + <span class=\"kw-chiffre\">1</span> apparenté du 1ᵉʳ degré avec un cancer du spectre HNPCC large <span class=\"kw-chiffre\">avant 50 ans</span>.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Indications de la consultation d'oncogénétique chez un patient pris en charge pour CCR</h5>\n      <ul>\n        <li>Âge <span class=\"kw-chiffre\">&lt; 40 ans</span>.</li>\n        <li>Phénotype <span class=\"kw-bio\">MSI+ / dMMR</span> sur la tumeur.</li>\n        <li>ATCD personnel de cancer du spectre du Lynch.</li>\n        <li>Parents au 1ᵉʳ degré atteints par un cancer du spectre, dont 1 cas <span class=\"kw-chiffre\">avant 50 ans</span>.</li>\n        <li>Suspicion de polypose : <span class=\"kw-chiffre\">&gt; 10 polypes adénomateux colorectaux</span> synchrones ou métachrones.</li>\n      </ul>\n\n      <h5>Tests génétiques somatiques au <span class=\"kw-def\">stade</span> métastatique</h5>\n      <p>Au-delà du <span class=\"kw-def\">dépistage</span> du Lynch / PAF, le séquençage somatique est indiqué au <span class=\"kw-def\">stade</span> métastatique pour guider la <span class=\"kw-ttt\">biothérapie</span> :</p>\n      <ul>\n        <li>Recherche de mutations <span class=\"kw-bio\">NRAS</span>, <span class=\"kw-bio\">KRAS</span>, <span class=\"kw-bio\">BRAF</span>.</li>\n        <li>Statut <span class=\"kw-bio\">MSI</span> (orientant vers une <span class=\"kw-ttt\">immunothérapie</span>).</li>\n        <li><span class=\"kw-ci\">Si KRAS ou NRAS muté → anti-EGFR contre-indiqués</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <strong>Démarche</strong> : confirmation de la mutation constitutionnelle = séquençage des gènes MMR sur prise de sang après <strong>consultation d'oncogénétique dédiée</strong> ; si mutation retrouvée → diagnostic chez <span class=\"kw-clinique\">les</span> apparentés possible.</div>","frequence":0},{"id":"301-11","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’une polypose adénomateuse familiale (PAF)","contenu":"<p>La <span class=\"kw-def\">polypose adénomateuse familiale (PAF)</span> est une maladie <span class=\"kw-etio\">héréditaire</span> rare mais redoutable : sans traitement prophylactique, la dégénérescence en CCR est <strong>quasi-systématique</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Gène muté</strong></td>\n            <td>Mutation du gène suppresseur de tumeur <span class=\"kw-bio\">APC</span>, situé sur le bras long du chromosome 5 (<span class=\"kw-bio\">5q21-q22</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Transmission</strong></td>\n            <td><span class=\"kw-def\">Autosomique dominante</span> (risque <span class=\"kw-chiffre\">50 %</span> à chaque enfant) ; <span class=\"kw-chiffre\">~20 %</span> de mutations de novo.</td>\n          </tr>\n          <tr>\n            <td><strong>Pénétrance</strong></td>\n            <td>Quasi-complète : la mutation entraîne quasi-constamment l'apparition du phénotype.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong></td>\n            <td><span class=\"kw-chiffre\">~1/10 000</span> — beaucoup plus rare que le Lynch.</td>\n          </tr>\n          <tr>\n            <td><strong>Définition clinique</strong></td>\n            <td>Présence de <span class=\"kw-chiffre\">&gt; 100 polypes adénomateux colorectaux</span> synchrones, apparaissant dès l'adolescence (~<span class=\"kw-chiffre\">10-12 ans</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Forme atténuée</strong></td>\n            <td>Variante de la PAF avec <span class=\"kw-chiffre\">&lt; 100 polypes</span>, apparition plus tardive ; à distinguer du <span class=\"kw-def\">syndrome MAP</span> (autosomique récessif, gène <span class=\"kw-bio\">MUTYH</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Rôle dans l'apparition d'un CCR</h5>\n      <ul>\n        <li>La PAF est responsable de <span class=\"kw-chiffre\">~1 %</span> de l'ensemble des CCR.</li>\n        <li>Individuellement, <span class=\"kw-clinique\">les</span> polypes de PAF <strong>ne sont pas plus susceptibles</strong> de dégénérer que ceux d'une personne non atteinte de PAF.</li>\n        <li>C'est le <strong>nombre élevé</strong> (centaines à milliers) qui rend la dégénérescence cumulative quasi-inéluctable : risque significatif dès <span class=\"kw-chiffre\">20-25 ans</span> ; <span class=\"kw-alerte\">dégénérescence systématique à partir de 40 ans</span>.</li>\n      </ul>\n\n      <h5>Manifestations extra-coliques</h5>\n      <ul>\n        <li><strong>Adénomes duodénaux</strong> (notamment ampullaires) — risque de dégénérescence, jusqu'à <span class=\"kw-chiffre\">80 %</span> des patients ⚠️.</li>\n        <li><strong>Tumeurs desmoïdes</strong> (mésentériques surtout) — bénignes mais source de complications loco-régionales et de <span class=\"kw-def\">mortalité</span>.</li>\n        <li><strong>Polypes gastriques bénins</strong> (~<span class=\"kw-chiffre\">50 %</span> des patients).</li>\n        <li><strong>Autres tumeurs</strong> : osseuses (ostéomes maxillaires — syndrome de <span class=\"kw-def\">Gardner</span>), thyroïdiennes, SNC.</li>\n        <li><strong>Manifestations bénignes</strong> : hypertrophie de l'épithélium p<span class=\"kw-chiffre\">igm</span>entaire de la rétine, anomalies dentaires, kystes épidermoïdes.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Surveillance</span> et <span class=\"kw-ttt\">chirurgie</span> prophylactique</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">Coloscopie</span> avec chromoendoscopie + biopsies <strong>dès la puberté</strong> (<span class=\"kw-chiffre\">10-12 ans</span>), <span class=\"kw-chiffre\">1×/an</span>.</li>\n        <li><span class=\"kw-imagerie\">Coloproctectomie totale</span> avec anastomose iléo-anale et réservoir : prophylactique, vers <span class=\"kw-chiffre\">20-25 ans</span> (polypes devenus trop nombreux).</li>\n        <li><span class=\"kw-imagerie\">FOGD</span> + biopsies de la papille : annuelle ou tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-3 ans</span>, à partir de <span class=\"kw-chiffre\">20-30 ans</span> (<span class=\"kw-def\">surveillance</span> des adénomes duodénaux).</li>\n        <li><span class=\"kw-def\">Surveillance</span> endoscopique du <strong>réservoir</strong> : tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> (anastomose iléo-anale) ou 1×/an (anastomose iléo-rectale).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>À ne pas confondre</strong> :<br>\n        — <span class=\"kw-def\">PAF</span> = autosomique <strong>dominante</strong>, gène <span class=\"kw-bio\">APC</span>, &gt; 100 polypes ;<br>\n        — <span class=\"kw-def\">MAP</span> = autosomique <strong>récessive</strong>, gène <span class=\"kw-bio\">MUTYH</span>, polypes 5-100, plus tardifs.\n      </div>","frequence":0},{"id":"301-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différentes étapes de l’examen clinique","contenu":"<p>L'examen clinique d'un patient suspect de cancer colorectal suit une séquence stéréotypée : <span class=\"kw-clinique\">interrogatoire</span> ciblé → <span class=\"kw-clinique\">examen général</span> → <span class=\"kw-clinique\">examen abdominal</span> → <span class=\"kw-clinique\">toucher rectal systématique</span> → <span class=\"kw-clinique\">recherche de complications</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Éléments clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Interrogatoire</strong></td>\n            <td>\n              <strong>FR personnels</strong> : âge, ATCD perso de polype / CCR / <span class=\"kw-clinique\">MICI</span> / acromégalie / <span class=\"kw-etio\">diabète</span> ;<br>\n              <strong>FR familiaux</strong> : CCR ou cancer du spectre Lynch chez apparenté 1ᵉʳ-2ᵉ degré, âge d'atteinte ;<br>\n              <strong>Mode de vie</strong> : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alimentation</span>, <span class=\"kw-etio\">sédentarité</span> ;<br>\n              <strong>Signes fonctionnels</strong> : <span class=\"kw-clinique\">rectorragies</span>, <span class=\"kw-clinique\">méléna</span>, <span class=\"kw-clinique\">troubles du transit récents</span>, <span class=\"kw-clinique\">douleurs abdo</span>, <span class=\"kw-clinique\">AEG</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Examen général</strong></td>\n            <td>\n              <strong>Poids, IMC, courbe pondérale</strong> — recherche d'<span class=\"kw-clinique\">AEG</span> ;<br>\n              <span class=\"kw-clinique\">OMS / performance status</span> — pré-thérapeutique ;<br>\n              <strong>Pâleur cutanéo-muqueuse</strong> — <span class=\"kw-bio\">anémie</span> ;<br>\n              <strong>Aires ganglionnaires</strong> : ganglion sus-claviculaire gauche de <span class=\"kw-clinique\">Troisier</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Examen abdominal</strong></td>\n            <td>\n              <strong>Inspection</strong> : ballonnement, cicatrices ;<br>\n              <strong>Palpation</strong> : <span class=\"kw-imagerie\">masse abdominale</span> (côlon droit +++), sensibilité localisée ;<br>\n              <strong>Recherche d'<span class=\"kw-clinique\">ascite</span></strong> et de <span class=\"kw-alerte\">carcinose péritonéale</span> (gâteau épiploïque, <span class=\"kw-clinique\">nodule</span> de Sœur Marie-Joseph ombilical) ;<br>\n              <strong><span class=\"kw-clinique\">Hépatomégalie</span> hétérogène</strong> ou « foie marronné » (M+ hépatiques).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4. Toucher rectal systématique</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">TR</span> sur rectum vide, en décubitus dorsal cuisses fléchies (ou genu-pectorale) :<br>\n              <strong>Distance</strong> à la marge anale et à la sangle pubo-rectale ;<br>\n              <strong>Taille</strong> (2 plus grands diamètres) et <strong>aspect</strong> (polypoïde sessile / pédiculé / ulcéré / ulcéro-bourgeonnant / infiltrant) ;<br>\n              <strong>Mobilité</strong> et <strong>fixation</strong> par rapport aux plans pariétaux profonds (fixation pariétale = risque de résection R2) ;<br>\n              <strong>Extension circonférentielle</strong> (mauvais <span class=\"kw-def\">pronostic</span> si circonférentiel) ;<br>\n              <strong>Nodules indurés</strong> dans le mésorectum ;<br>\n              <strong>Prostate</strong> (homme), <strong>doigtier sanglant</strong> à la sortie.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>5. Recherche de signes de complication</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Occlusion</span> : arrêt des matières et des gaz, météorisme, défense en FID en cas de souffrance caecale ;<br>\n              <span class=\"kw-alerte\">Péritonite</span> : défense, contracture (attention aux formes asthéniques du sujet âgé) ;<br>\n              <span class=\"kw-alerte\">Infection</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span> (<span class=\"kw-alerte\">endocardite à <em><span class=\"kw-etio\">Streptococcus gallolyticus</span></em></span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Syndrome rectal — sémiologie spécifique du cancer du rectum</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Épreintes</span> : douleurs coliques/pelviennes accompagnées d'un spasme rectal, soulagées par l'émission de selles.</li>\n        <li><span class=\"kw-clinique\">Ténesme</span> : tension douloureuse dans la région anale, persistante après l'exonération.</li>\n        <li><span class=\"kw-clinique\">Faux besoins / impériosité</span> : émissions de glaires par l'anus.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ Le <strong>toucher rectal</strong> est <span class=\"kw-alerte\">obligatoire</span> devant tout signe digestif évocateur. Il diagnostique <span class=\"kw-clinique\">les</span> cancers du moyen et du bas rectum (intracliniquement accessibles), permet de mesurer la marge à la sangle pubo-rectale (= déterminant chirurgical), et de palper d'éventuels nodules de carcinose dans le cul-de-sac de Douglas.</div>","frequence":1},{"id":"301-13","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention","contenu":"<p>Objectif EDN à <strong>très haute valeur</strong> (4 ⭐). Trois axes : <strong><span class=\"kw-def\">diagnostic positif</span></strong> (<span class=\"kw-bio\">histologie</span>), <strong><span class=\"kw-def\">bilan d'extension</span></strong> (<span class=\"kw-imagerie\">TDM</span> TAP, marqueurs), <strong><span class=\"kw-ci\">bilan pré-thérapeutique</span></strong>.</p>\n\n      <h5>Côlon <span class=\"kw-bio\">vs</span> rectum — vue d'ensemble</h5>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>ADK colique</th><th>Cancer du rectum</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Coloscopie totale + biopsies</span></td>\n            <td><strong>Gold standard</strong> du <span class=\"kw-def\">diagnostic positif</span> (jusqu'à la dernière anse iléale).</td>\n            <td>Idem. <span class=\"kw-imagerie\">Coloscopie</span> courte tolérée en <span class=\"kw-alerte\">urgence</span>, mais <span class=\"kw-imagerie\">coloscopie</span> totale à compléter pour exclure une <span class=\"kw-clinique\">lésion</span> synchrone.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM TAP injecté</span></td>\n            <td><strong>Systématique</strong> — <span class=\"kw-def\">bilan d'extension</span> (poumon, foie, péritoine, ganglions).</td>\n            <td>Systématique également.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">ACE (antigène carcino-embryonnaire)</span></td>\n            <td><strong>Pré-thérapeutique uniquement</strong>, après confirmation histologique. Sert de valeur de référence pour le <span class=\"kw-def\">suivi</span>.</td>\n            <td>Idem (± <span class=\"kw-bio\">CA 19-9</span> si <span class=\"kw-bio\">ACE</span> non disponible).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM pelvienne</span></td>\n            <td>Non systématique (sauf doute charnière recto-s<span class=\"kw-chiffre\">igm</span>oïdienne).</td>\n            <td><strong>Systématique</strong> — mesure la <span class=\"kw-imagerie\">marge circonférentielle</span> au fascia recti, le T-<span class=\"kw-def\">stade</span> local, l'<span class=\"kw-bio\">envahissement</span> du mésorectum.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Écho-endoscopie rectale</span></td>\n            <td>—</td>\n            <td>Pour <span class=\"kw-clinique\">les</span> <strong>petites tumeurs T1-T2</strong> superficielles (<span class=\"kw-def\">classification</span> usTNM).</td>\n          </tr>\n          <tr>\n            <td>Bilan <span class=\"kw-ttt\">biologique</span> pré-op</td>\n            <td colspan=\"2\">\n              <strong>Standards</strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan d'hémostase</span>, bilan transfusionnel.<br>\n              <strong>Bilan nutritionnel</strong> : <span class=\"kw-bio\">albumine</span>, pré-<span class=\"kw-bio\">albumine</span>, <span class=\"kw-bio\">bilan martial</span>.<br>\n              <strong>Fonction d'organes</strong> : <span class=\"kw-bio\">bilan rénal</span>, <span class=\"kw-bio\">bilan hépatique</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-imagerie\">Coloscopie</span> totale — points clés</h5>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Étendue</strong></td>\n            <td>Exploration du rectum et de tout le cadre colique jusqu'à la <span class=\"kw-imagerie\">dernière anse iléale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Biopsies</strong></td>\n            <td><span class=\"kw-imagerie\">Biopsies multiples</span> de toute <span class=\"kw-clinique\">lésion</span> suspecte pour analyse histologique.</td>\n          </tr>\n          <tr>\n            <td><strong>Aspect endoscopique</strong></td>\n            <td><span class=\"kw-imagerie\">Tumeur bourgeonnante, ± ulcérée, dure sous la pince, fragile, saignant au contact</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Préparation</strong></td>\n            <td><span class=\"kw-ttt\">Consultation d'anesthésie (AG)</span> ; <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, albuminémie ; <span class=\"kw-ttt\">régime sans résidu <span class=\"kw-chiffre\">3-5 jours</span></span> ; <span class=\"kw-ttt\">PEG <span class=\"kw-chiffre\">3-4 L</span></span> la veille et le matin.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">AVK</span> / <span class=\"kw-ttt\">antiagrégants</span></strong></td>\n            <td>Endoscopie possible sous <span class=\"kw-ttt\">bi-antiagrégation</span> ; <span class=\"kw-ci\">arrêt des AVK</span> justifié, ± relai <span class=\"kw-ttt\">héparine</span> si haut risque thrombo-<span class=\"kw-etio\">embolique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>CI à la préparation</strong></td>\n            <td><span class=\"kw-alerte\">Syndrome subocclusif</span> → <span class=\"kw-ttt\">lavements</span> à la place.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Coloscopie</span> incomplète</strong></td>\n            <td><span class=\"kw-imagerie\">Coloscanner</span> ou <span class=\"kw-imagerie\">coloscopie</span> virtuelle en <span class=\"kw-bio\">complément</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-imagerie\">TDM</span> TAP injecté — <span class=\"kw-def\">bilan d'extension</span></h5>\n      <table >\n        <thead>\n          <tr><th>Cible</th><th>Sémiologie radiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeur colique primitive</strong></td>\n            <td><span class=\"kw-imagerie\">Image en « trognon de pomme »</span>, angles de raccordement brutaux, sténose courte, circonférentielle, irrégulière.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">M+ hépatiques</span></strong></td>\n            <td>Spontanément <span class=\"kw-imagerie\">hypodenses</span>, non rehaussées au temps artériel, couronne au temps portal.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">M+ pulmonaires</span></strong></td>\n            <td>Nodules multiples, arrondis, à contours nets, basaux périphériques ; <strong>non calcifiées</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Carcinose péritonéale</span></strong></td>\n            <td>Épaississement péritonéal, <span class=\"kw-ttt\">infiltration</span> de la graisse, nodules, <span class=\"kw-imagerie\">gâteau épiploïque</span>, <span class=\"kw-clinique\">ascite</span> (<span class=\"kw-chiffre\">70 %</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Statut cN+</strong></td>\n            <td>Visualisation de mauvaise qualité au <span class=\"kw-imagerie\">scanner</span>, mais <span class=\"kw-ci\">ne modifie pas la stratégie thérapeutique</span> pour le cancer du côlon.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Imagerie spécifique du rectum — <span class=\"kw-imagerie\">IRM</span> pelvienne</h5>\n      <ul>\n        <li>Mesure la <span class=\"kw-imagerie\">marge circonférentielle</span> (plus courte distance entre la tumeur et le fascia recti).</li>\n        <li><span class=\"kw-imagerie\">Marge circonférentielle &lt; 1 mm</span> à l'<span class=\"kw-imagerie\">IRM</span> → <span class=\"kw-alerte\">remet en question la possibilité d'une exérèse curative</span>, indication de radio-<span class=\"kw-ttt\">chimiothérapie</span> néoadjuvante.</li>\n        <li>Évalue l'extension dans le mésorectum, <span class=\"kw-clinique\">les</span> ganglions péri-rectaux.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <strong>Pas de <span class=\"kw-imagerie\">TEP-FDG</span> en bilan initial systématique</strong>. Indications limitées : <span class=\"kw-imagerie\">bilan de résécabilité des <span class=\"kw-alerte\">M+ hépatiques</span></span> avant <span class=\"kw-ttt\">chirurgie</span>, ou élévation isolée de l'<span class=\"kw-bio\">ACE</span> avec <span class=\"kw-imagerie\">TDM</span> normale.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 293 — <span class=\"kw-bio\">Anatomopathologie</span></em></p>","frequence":4},{"id":"301-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires endoscopiques et radiologiques","contenu":"<p>Au-delà de la <span class=\"kw-imagerie\">coloscopie</span> totale et du <span class=\"kw-imagerie\">TDM</span> TAP (cf. obj-12), plusieurs examens endoscopiques et radiologiques peuvent être indiqués selon la localisation <span class=\"kw-etio\">tumorale</span> et la situation clinique.</p>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Coloscopie totale</span></td>\n            <td>\n              Gold standard du <span class=\"kw-def\">diagnostic positif</span>. Chromoendoscopie (indigo-carmin) pour <span class=\"kw-clinique\">les</span> <strong>adénomes plans</strong> du Lynch / PAF.<br>\n              <strong>Marquage / tatouage</strong> de la <span class=\"kw-clinique\">lésion</span> en <span class=\"kw-imagerie\">endoscopie</span> pour faciliter la <span class=\"kw-ttt\">chirurgie</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Recto-sigmoïdoscopie</span></td>\n            <td>Utilisée en <span class=\"kw-alerte\">urgence</span> ou si <span class=\"kw-imagerie\">coloscopie</span> totale impossible (préparation insuffisante, tumeur infranchissable). Insuffisante pour exclure une <span class=\"kw-clinique\">lésion</span> synchrone d'amont.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Coloscanner / coloscopie virtuelle</span></td>\n            <td>\n              En <span class=\"kw-bio\">complément</span> si <span class=\"kw-imagerie\">coloscopie</span> incomplète (préparation insuffisante, <span class=\"kw-clinique\">lésion</span> obstructive).<br>\n              <strong>Coloscanner à l'eau</strong> : lavement par l'anus, puis <span class=\"kw-imagerie\">TDM</span> abdominale.<br>\n              <strong><span class=\"kw-imagerie\">Coloscopie</span> virtuelle</strong> : marquage opacifiant des résidus, insufflation de CO₂, reconstructions 3D.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM TAP injecté</span></td>\n            <td>\n              <strong>Systématique</strong> en <span class=\"kw-def\">bilan d'extension</span> : poumon, foie, péritoine, ganglions.<br>\n              Aspect typique de la tumeur : « <strong>trognon de pomme</strong> ».\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM pelvienne</span></td>\n            <td>\n              <strong>Systématique</strong> pour tout cancer du rectum.<br>\n              Mesure la marge circonférentielle au fascia recti, le T-<span class=\"kw-def\">stade</span> local, l'<span class=\"kw-bio\">envahissement</span> du mésorectum et des ganglions péri-rectaux.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Écho-endoscopie rectale</span></td>\n            <td>\n              Pour <span class=\"kw-clinique\">les</span> <strong>petites lésions T1-T2</strong> superficielles (<span class=\"kw-def\">classification</span> usTNM).<br>\n              Discrimine l'extension pariétale couche par couche.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM hépatique injectée (gadolinium ± diffusion)</span></td>\n            <td>\n              <strong>Non systématique</strong>. Indiquée si M+ hépatiques résécables ou potentiellement résécables sur le <span class=\"kw-imagerie\">TDM</span> initial.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TEP-FDG</span></td>\n            <td>\n              <strong>Non systématique en bilan initial</strong>. Indications : bilan de résécabilité des <span class=\"kw-alerte\">M+ hépatiques</span> avant <span class=\"kw-ttt\">chirurgie</span>, élévation isolée de l'<span class=\"kw-bio\">ACE</span> avec <span class=\"kw-imagerie\">TDM</span> normale, recherche de récidive.<br>\n              <span class=\"kw-ci\">N'a pas de place dans la surveillance routinière du CCR opéré</span> (piège annale).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Ne pas confondre tumeur infranchissable et tumeur en occlusion</strong>. Une tumeur infranchissable à l'<span class=\"kw-imagerie\">endoscopie</span> ne signifie pas que le patient est en occlusion : l'occlusion est un diagnostic <span class=\"kw-alerte\">CLINIQUE</span> (arrêt des matières et des gaz, météorisme, <span class=\"kw-clinique\">AEG</span>).</div>\n\n      <div class=\"callout callout-info\">📌 La <span class=\"kw-imagerie\">coloscopie en urgence</span> est <span class=\"kw-ci\">contre-indiquée</span> en cas d'occlusion colique (risque de <span class=\"kw-alerte\">perforation diastatique du cæcum</span>). Préférer le <span class=\"kw-imagerie\">TDM AP injecté</span> ± opacification basse.</div>","frequence":1},{"id":"301-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie initiale du cancer du colon","contenu":"<p>La stratégie d'imagerie initiale d'un cancer du côlon suit une séquence <strong><span class=\"kw-def\">diagnostic positif</span> → <span class=\"kw-def\">bilan d'extension</span> → <span class=\"kw-ci\">bilan pré-thérapeutique</span></strong>. Elle est différente de celle du rectum (qui requiert en plus une <span class=\"kw-imagerie\">IRM</span> pelvienne et parfois une <span class=\"kw-imagerie\">écho-endoscopie</span>).</p>\n\n      <h5>Séquence stratégique</h5>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Examen</th><th>Objectif</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td><span class=\"kw-imagerie\">Coloscopie totale + biopsies multiples</span></td>\n            <td>Histologique : seul examen qui pose le diagnostic.</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Bilan d'extension</span></strong></td>\n            <td><span class=\"kw-imagerie\">TDM TAP injecté</span> <strong>systématique</strong></td>\n            <td>\n              Recherche des M+ :<br>\n              <strong>Hépatiques</strong> en 1ᵉʳ (synchrones <span class=\"kw-chiffre\">20-30 %</span>) ;<br>\n              <strong>Pulmonaires</strong> (nodules basaux périphériques non calcifiés) ;<br>\n              <strong>Péritonéales</strong> (carcinose : <span class=\"kw-clinique\">ascite</span>, gâteau épiploïque, nodules) ;<br>\n              <strong>Ganglionnaires</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Marqueur</strong></td>\n            <td><span class=\"kw-bio\">ACE pré-thérapeutique</span></td>\n            <td>Valeur de référence pour le <span class=\"kw-def\">suivi</span> (recommandé uniquement après confirmation histologique, jamais pour le <span class=\"kw-def\">dépistage</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>4. Imagerie non systématique</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">IRM hépatique</span> si doute sur le <span class=\"kw-imagerie\">TDM</span> ou bilan de résécabilité des M+ ;<br>\n              <span class=\"kw-imagerie\">TEP-FDG</span> si <span class=\"kw-ttt\">chirurgie</span> hépatique envisagée OU élévation isolée de l'<span class=\"kw-bio\">ACE</span> avec <span class=\"kw-imagerie\">TDM</span> normale.\n            </td>\n            <td>Optimiser la stratégie thérapeutique pour <span class=\"kw-clinique\">les</span> M+.</td>\n          </tr>\n          <tr>\n            <td><strong>5. Cas particuliers</strong></td>\n            <td><span class=\"kw-imagerie\">IRM pelvienne</span> si doute avec une <span class=\"kw-clinique\">lésion</span> du <strong>haut rectum</strong> devant un CCR de la charnière recto-s<span class=\"kw-chiffre\">igm</span>oïdienne.</td>\n            <td>Précise le siège exact (côlon <span class=\"kw-bio\">vs</span> rectum) et donc la stratégie thérapeutique (<span class=\"kw-ttt\">chirurgie</span> immédiate <span class=\"kw-bio\">vs</span> <span class=\"kw-imagerie\">RT</span>-CT néoadjuvante).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Différences clés côlon <span class=\"kw-bio\">vs</span> rectum</h5>\n      <ul>\n        <li>Côlon : <span class=\"kw-ci\">pas d'IRM systématique</span> ; le statut cN+ au <span class=\"kw-imagerie\">TDM</span> ne modifie pas la stratégie thérapeutique.</li>\n        <li>Rectum : <span class=\"kw-imagerie\">IRM pelvienne systématique</span> (mesure de la marge circonférentielle au fascia recti, T-<span class=\"kw-def\">stade</span> local) ; ± <span class=\"kw-imagerie\">écho-endoscopie</span> rectale pour T1-T2.</li>\n        <li>Côlon : pas de <span class=\"kw-imagerie\">TEP</span> en bilan initial systématique.</li>\n      </ul>\n\n      <h5><span class=\"kw-ci\">Bilan pré-thérapeutique</span> associé</h5>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Examens / Précisions</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie standard</strong></td>\n            <td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">bilan d'hémostase</span> ; <span class=\"kw-bio\">bilan transfusionnel</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan nutritionnel</strong></td>\n            <td><span class=\"kw-bio\">albumine</span> ; <span class=\"kw-bio\">pré-albumine</span> ; <span class=\"kw-bio\">bilan martial</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fonction d'organes</strong></td>\n            <td><span class=\"kw-bio\">bilan rénal</span> ; <span class=\"kw-bio\">bilan hépatique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Phénotype <span class=\"kw-bio\">MSI+</span></strong></td>\n            <td>Recherche systématique si <span class=\"kw-chiffre\">âge &lt; 70 ans</span>, <span class=\"kw-etio\">ATCD familiaux</span>, ou <span class=\"kw-alerte\">stade métastatique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Test <span class=\"kw-etio\">génétique</span> somatique</strong></td>\n            <td>Au <span class=\"kw-alerte\">stade métastatique</span> : <span class=\"kw-bio\">NRAS</span>, <span class=\"kw-bio\">KRAS</span>, <span class=\"kw-bio\">BRAF</span>, <span class=\"kw-bio\">MSI</span> (<span class=\"kw-ci\">anti-EGFR contre-indiqués si KRAS/NRAS muté</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Récidives</strong> : <span class=\"kw-chiffre\">~80 %</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 premières années</span> post-traitement curatif, principalement <span class=\"kw-alerte\">métastatiques</span> (<span class=\"kw-alerte\">foie +++</span>). Cela justifie une <span class=\"kw-imagerie\">surveillance écho/TDM hépatique</span> rapprochée pendant les <span class=\"kw-chiffre\">3 premières années</span> (mais pas de <span class=\"kw-imagerie\">TEP</span>, pas d'<span class=\"kw-bio\">ACE</span> — d'intérêt non démontré).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeurs du foie, primitives et secondaires</em></p>","frequence":3},{"id":"301-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes de traitement des cancers localisés","contenu":"<p>La prise en charge d'un CCR localisé est <strong>radicalement différente</strong> entre le côlon (<span class=\"kw-ttt\">chirurgie</span> d'emblée, pas de néoadjuvant) et le rectum (radio-<span class=\"kw-ttt\">chimiothérapie</span> néoadjuvante pour le bas/moyen rectum). Sujet à <strong>très haute valeur</strong> (4 ⭐).</p>\n\n      <h5>Vue d'ensemble — ADK colique <span class=\"kw-bio\">vs</span> cancer du rectum</h5>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>ADK colique non métastatique, non compliqué</th><th>Cancer du rectum localisé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Néoadjuvant</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Immuno-nutrition</span> pré-opératoire <span class=\"kw-chiffre\">7 jours</span>, quel que soit l'état nutritionnel.<br>\n              <span class=\"kw-ci\">Pas de traitement néoadjuvant médicamenteux</span>.\n            </td>\n            <td>\n              <span class=\"kw-ttt\">Radio-chimiothérapie néoadjuvante</span> (<span class=\"kw-chiffre\">3 mois</span>), lésions du <strong>bas/moyen rectum</strong> :<br>\n              <strong>Indications indiscutables</strong> : <span class=\"kw-imagerie\">marge circonférentielle ≤ 1 mm</span>, tumeur T4 ;<br>\n              <strong>Indications relatives</strong> : cTN+, ou T2-T3 avec marge circonférentielle petite.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span></strong></td>\n            <td>\n              <strong>Voie d'abord</strong> : cœlioscopie (sauf cT4).<br>\n              <strong>Marges</strong> : <span class=\"kw-chiffre\">≥ 5 cm</span> de part et d'autre de la tumeur.<br>\n              <strong>Côlon droit</strong> (cæcum, ascendant, angle droit) : <span class=\"kw-imagerie\">hémicolectomie droite</span> + curage iléo-cæco-colo-appendiculaire et colique sup droit + <span class=\"kw-ttt\">exérèse</span> du mésocôlon. <span class=\"kw-ci\">Pas de section à l'origine de l'AMS</span> (risque de <span class=\"kw-clinique\">nécrose</span> du grêle). Anastomose iléo-colique transverse.<br>\n              <strong>Côlon gauche</strong> (descendant, s<span class=\"kw-chiffre\">igm</span>oïde) : <span class=\"kw-imagerie\">colectomie gauche</span> + curage AMI. <span class=\"kw-imagerie\">Section à l'origine de l'AMI possible</span>. Anastomose colo-rectale.<br>\n              <strong><span class=\"kw-ttt\">Curage ganglionnaire</span></strong> : <span class=\"kw-chiffre\">≥ 12 ganglions</span> sur la pièce.\n            </td>\n            <td>\n              <strong>Haut rectum (<span class=\"kw-chiffre\">10-15 cm</span>)</strong> : résection partielle du mésorectum + anastomose colorectale <span class=\"kw-chiffre\">5 cm</span> sous le pôle inférieur.<br>\n              <strong>Moyen / bas rectum</strong> : <span class=\"kw-imagerie\">exérèse totale du mésorectum</span> ; puis :<br>\n              — Moyen rectum ou marge distale &gt; <span class=\"kw-chiffre\">1 cm</span> : anastomose colo-anale latéro-terminale ou réservoir colique ;<br>\n              — Bas rectum, marge <span class=\"kw-chiffre\">&lt; 1 cm du sphincter externe</span> : <span class=\"kw-alerte\">amputation abdomino-périnéale (APR)</span> + <span class=\"kw-alerte\">colostomie gauche définitive</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adjuvant</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Stade</span> I</strong> (T1-T2 N0) : pas de traitement adjuvant, <span class=\"kw-def\">surveillance</span>.<br>\n              <strong><span class=\"kw-chiffre\">Stade II</span></strong> (T3-T4 N0) : <span class=\"kw-ttt\">chimio adjuvante</span> discutée en <span class=\"kw-def\">RCP</span> au cas par cas (selon FR de mauvais <span class=\"kw-def\">pronostic</span>).<br>\n              <strong><span class=\"kw-chiffre\">Stade III</span></strong> (N+) : <span class=\"kw-ttt\">chimio adjuvante systématique</span>.\n            </td>\n            <td>\n              <strong><span class=\"kw-def\">Stade</span> III</strong> (N+) : <span class=\"kw-ttt\">chimio adjuvante</span>, qu'il y ait eu ou non <span class=\"kw-imagerie\">RT</span>-CT néoadjuvante.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Cas particuliers — résection endoscopique</h5>\n      <ul>\n        <li><strong>Cancer in situ (intra-muqueux / pTis)</strong> : la <span class=\"kw-imagerie\">résection endoscopique</span> peut être un traitement suffisant si limites de résection saines (R0).</li>\n        <li><strong>Cancer T1 superficiel (sous-muqueux)</strong> : résection endoscopique suffisante si <span class=\"kw-bio\">envahissement</span> sous-muqueux superficiel <strong>et</strong> R0. Sinon dossier en <span class=\"kw-def\">RCP</span>.</li>\n        <li><strong>Cancer du rectum T1 superficiel</strong> : <span class=\"kw-ttt\">exérèse</span> locale par voie transanale envisageable (risque de M+ ganglionnaire voisin de 0).</li>\n      </ul>\n\n      <h5>Points clés à retenir</h5>\n      <ul>\n        <li><span class=\"kw-ttt\">Immunonutrition</span> <span class=\"kw-chiffre\">7 jours</span> pré-opératoires <strong>systématique côlon</strong>, quel que soit l'état nutritionnel.</li>\n        <li><span class=\"kw-imagerie\">Marges</span> : <span class=\"kw-chiffre\">≥ 5 cm</span> côlon ; circonférentielle &gt; <span class=\"kw-chiffre\">1 mm</span> rectum.</li>\n        <li><span class=\"kw-imagerie\">Curage</span> : ≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>12</span> g</span>anglions examinés sur la pièce (qualité du staging et critère pronostique).</li>\n        <li><span class=\"kw-imagerie\">RT-CT néoadjuvante</span> uniquement pour bas / moyen rectum, indications <span class=\"kw-imagerie\">IRM</span>-guidées.</li>\n        <li><span class=\"kw-alerte\">APR + colostomie définitive</span> si bas rectum avec marge &lt; <span class=\"kw-chiffre\">1 cm</span> du sphincter externe — décision lourde, retentissement majeur sur la qualité de vie.</li>\n        <li><span class=\"kw-ttt\">Chimio adjuvante</span> indiquée au <span class=\"kw-def\">stade</span> III ; discutée au <span class=\"kw-chiffre\">stade II</span> selon FR ACP.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-ttt\">Curage ganglionnaire</span></strong> : la qualité du curage est un facteur pronostique majeur. Examen anatomopathologique de <span class=\"kw-chiffre\">≥ 12 ganglions</span> recommandé ; l<span class=\"kw-chiffre\">iga</span>ture des vaisseaux à leur origine (ganglions satellites de la vascularisation artérielle).</div>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>CCR métastatique</strong> (hors scope obj-15 mais pertinent) : si M+ hépatiques résécables, <span class=\"kw-ttt\">chirurgie</span> hépatique première / colique première / combinée + chimio péri-opératoire. Si non résécables : chimio exclusive ± <span class=\"kw-ttt\">biothérapie</span> (<span class=\"kw-ttt\">anti-VEGF</span> ou <span class=\"kw-ttt\">anti-EGFR</span> selon statut RAS, <span class=\"kw-ci\">anti-EGFR CI si KRAS/NRAS muté</span>).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Accompagnement du malade cancéreux</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Occlusion sur cancer colique <span class=\"q\">— complication révélatrice la plus fréquente</span></strong></p><p>Traiter l'occlusion en <span class=\"kw-alerte\">urgence</span> (le traitement carcinologique sera fait secondairement) ; <span class=\"kw-imagerie\">TDM AP injectée</span> ± opacification basse</p><ul><li>Le cancer est la <span class=\"kw-etio\">1re cause d'occlusion colique</span>, au <span class=\"kw-def\">côlon gauche</span> dans <span class=\"kw-chiffre\">70 %</span> (petit <span class=\"kw-clinique\">diamètre</span>, selles solides, sténose en virole)</li><li>Révélation par une occlusion = <span class=\"kw-alerte\">facteur de mauvais pronostic</span></li><li><span class=\"kw-ci\">Coloscopie en urgence contre-indiquée</span> ; <span class=\"kw-ci\">prothèse endoscopique contre-indiquée</span> (risque de perforation <span class=\"kw-etio\">tumorale</span>, sauf palliatif / <span class=\"kw-def\">comorbidités</span> lourdes)</li></ul><p><strong>Souffrance diastatique du cæcum <span class=\"q\">— sur occlusion du côlon gauche</span></strong></p><p><span class=\"kw-ttt\">Chirurgie en urgence centrée sur le cæcum</span> (résection + iléo-colostomie) — sinon <span class=\"kw-ttt\">colostomie de décharge d'amont</span></p><ul><li><span class=\"kw-alerte\">Douleur ± défense en fosse iliaque droite</span></li><li><span class=\"kw-alerte\">Pneumatose pariétale</span>, défaut de rehaussement de la paroi, <span class=\"kw-alerte\">risque de perforation diastatique</span> si cæcum <span class=\"kw-chiffre\">≥ 9-12 cm</span></li></ul><p><strong>Cancer perforé avec <span class=\"kw-clinique\">péritonite</span></strong></p><p><span class=\"kw-ttt\">Intervention de Hartmann</span> (<span class=\"kw-ttt\">exérèse</span> de la tumeur + perforation, sans anastomose)</p><ul><li><span class=\"kw-alerte\">Défense / contracture</span> (attention aux péritonites asthéniques), plus fréquent au <span class=\"kw-def\">côlon gauche</span></li><li>Perforation in situ ou diastatique du cæcum en amont d'une tumeur sténosante</li></ul><p><strong>Cancer abcédé <span class=\"q\">— rare</span></strong></p><p><span class=\"kw-ttt\">Antibiothérapie</span> de l'<span class=\"kw-clinique\">abcès</span>, puis bilan oncologique secondaire</p><ul><li>L'<span class=\"kw-clinique\">abcès</span> majore le risque chirurgical et peut modifier le geste opératoire</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> la <span class=\"kw-imagerie\">coloscopie totale</span> diagnostique (sous <span class=\"kw-ttt\">AG</span>, après consultation d'anesthésie) ne requiert pas d'<span class=\"kw-alerte\">hospitalisation</span> et peut se faire en hospitalisation de jour.<br><strong><span class=\"kw-def\">RCP</span> systématique :</strong> toute décision thérapeutique (adénocarcinome <span class=\"kw-def\">pT1</span> sur polype, résection endoscopique incomplète, résécabilité des <span class=\"kw-etio\">métastases hépatiques</span>) est posée en <span class=\"kw-def\">réunion de concertation pluridisciplinaire</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> chirurgicale / hospitalisation :</strong> <span class=\"kw-alerte\">occlusion</span>, <span class=\"kw-alerte\">perforation</span>, <span class=\"kw-alerte\">péritonite</span> ou cancer abcédé révélateurs.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Douleur ± défense en fosse iliaque droite</span> sur occlusion = souffrance du cæcum (perforation imminente)</li><li><span class=\"kw-alerte\">Défense / contracture</span> = perforation avec <span class=\"kw-clinique\">péritonite</span> (méfiance des formes asthéniques)</li><li>Révélation par une <span class=\"kw-alerte\">occlusion</span> = facteur de mauvais <span class=\"kw-def\">pronostic</span></li><li><span class=\"kw-alerte\">Marge circonférentielle &lt; 1 mm</span> à l'<span class=\"kw-imagerie\">IRM</span> rectale → reconsidérer <span class=\"kw-clinique\">les</span> chances d'<span class=\"kw-ttt\">exérèse</span> curative</li><li><span class=\"kw-clinique\">Adénopathie sus-claviculaire gauche</span> (Troisier), <span class=\"kw-clinique\">nodule de Sœur Marie-Joseph</span> ombilical, <span class=\"kw-clinique\">ascite</span> → carcinose / maladie métastatique</li><li><span class=\"kw-clinique\">Anémie ferriprive</span> par saignement occulte (surtout côlon droit) → évoquer un CCR</li></ul>","principes":"<p><strong>Règle d'or :</strong> <span class=\"kw-ttt\">exérèse</span> <span class=\"kw-def\">R0</span> avec marges et <span class=\"kw-ttt\">curage ganglionnaire</span> (<span class=\"kw-chiffre\">≥ 12 ganglions</span> examinés = qualité du staging + critère pronostique) ; tout traitement péri-opératoire est posé en <span class=\"kw-def\">RCP</span> selon le <span class=\"kw-def\">stade</span> TNM.</p><p><strong>Lésions superficielles (Tis / T1)</strong></p><ul><li><span class=\"kw-ttt\">Résection endoscopique</span> suffisante si <span class=\"kw-clinique\">carcinome</span> in situ / T1 superficiel avec limites saines (<span class=\"kw-def\">R0</span>)</li><li>Rectum T1 : <span class=\"kw-ttt\">exérèse locale transanale</span> possible (risque ganglionnaire ≈ 0)</li><li>Adénocarcinome <span class=\"kw-def\">pT1</span> découvert sur la pièce → dossier en <span class=\"kw-def\">RCP</span></li></ul><p><strong>Cancer du côlon localisé</strong></p><ul><li><span class=\"kw-ttt\">Immuno-nutrition</span> pré-opératoire <span class=\"kw-chiffre\">7 jours</span> ; <span class=\"kw-ci\">pas de traitement néoadjuvant</span></li><li><span class=\"kw-ttt\">Colectomie carcinologique</span>, marges <span class=\"kw-chiffre\">≥ 5 cm</span> : côlon droit = hémicolectomie droite (<span class=\"kw-ci\">pas de section à l'origine de l'AMS</span>) ; côlon gauche = colectomie gauche (section à l'origine de l'AMI possible)</li><li><span class=\"kw-ttt\">Chimiothérapie adjuvante</span> si <span class=\"kw-def\">stade</span> III (N+) ; discutée au cas par cas au <span class=\"kw-chiffre\">stade II</span></li></ul><p><strong>Cancer du rectum localisé</strong></p><ul><li><span class=\"kw-ttt\">Radiochimiothérapie néoadjuvante</span> pour le <span class=\"kw-def\">bas / moyen rectum</span> : indiscutable si <span class=\"kw-chiffre\">marge circonférentielle ≤ 1 mm</span> ou tumeur <span class=\"kw-def\">T4</span></li><li>Haut rectum = résection partielle du mésorectum ; moyen / bas rectum = <span class=\"kw-ttt\">exérèse totale du mésorectum (TME)</span></li><li>Bas rectum à <span class=\"kw-chiffre\">&lt; 1 cm du sphincter externe</span> → <span class=\"kw-ttt\">amputation abdomino-périnéale</span> + <span class=\"kw-alerte\">colostomie définitive</span></li><li><span class=\"kw-ttt\">Chimiothérapie adjuvante</span> si <span class=\"kw-def\">stade</span> III post-opératoire (N+)</li></ul>","suivi":"<p><strong>Après traitement curatif d'un CCR</strong></p><ul><li><span class=\"kw-imagerie\">Coloscopie</span> à <span class=\"kw-chiffre\">1 an</span>, <span class=\"kw-chiffre\">3 ans</span>, <span class=\"kw-chiffre\">5 ans</span> (quel que soit le <span class=\"kw-def\">stade</span>) ; si incomplète en pré-op, à refaire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> post-op</li><li>Stades II-III : <span class=\"kw-clinique\">examen clinique</span> + <span class=\"kw-imagerie\">échographie abdominale</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> (<span class=\"kw-chiffre\">3 ans</span>) puis <span class=\"kw-chiffre\">6 mois</span> (<span class=\"kw-chiffre\">2 ans</span>) ; <span class=\"kw-imagerie\">RXT</span> tous les <span class=\"kw-chiffre\">6 mois</span> puis annuelle</li><li><span class=\"kw-ci\">Surveillance de l'ACE non recommandée</span> ; <span class=\"kw-ci\">pas de TEP</span> dans la <span class=\"kw-def\">surveillance</span> (pièges d'annale)</li></ul><p><strong><span class=\"kw-def\">Dépistage</span> organisé — risque moyen (<span class=\"kw-chiffre\">≥ 50 ans</span>, asymptomatique)</strong></p><ul><li><span class=\"kw-bio\">Test immunologique fécal (iFOBT)</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> entre <span class=\"kw-chiffre\">50-74 ans</span> (rôle clé du médecin traitant)</li><li><span class=\"kw-imagerie\">Coloscopie</span> si test positif ; si <span class=\"kw-imagerie\">coloscopie</span> normale, contrôle à <span class=\"kw-chiffre\">5 ans</span></li></ul><p><strong>Risque élevé (ATCD personnel / familial 1er degré, <span class=\"kw-clinique\">MICI</span>, acromégalie)</strong></p><ul><li><span class=\"kw-imagerie\">Coloscopie</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-5 ans</span> ; <span class=\"kw-ci\">pas de test immunologique</span></li><li>Début à <span class=\"kw-chiffre\">45 ans</span> ou <span class=\"kw-chiffre\">10 ans</span> avant l'âge du cas index</li></ul><p><strong>Risque très élevé — syndromes génétiques</strong></p><ul><li><span class=\"kw-etio\">Syndrome de Lynch</span> : <span class=\"kw-imagerie\">coloscopie avec chromoendoscopie</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> dès <span class=\"kw-chiffre\">20 ans</span> ; <span class=\"kw-def\">surveillance</span> endométriale dès <span class=\"kw-chiffre\">30 ans</span></li><li><span class=\"kw-etio\">PAF</span> : <span class=\"kw-imagerie\">coloscopie</span> annuelle dès <span class=\"kw-chiffre\">10-12 ans</span> puis <span class=\"kw-ttt\">chirurgie prophylactique</span> vers <span class=\"kw-chiffre\">20-25 ans</span></li><li><span class=\"kw-bio\">Test génétique</span> / consultation d'oncogénétique à poser selon <span class=\"kw-clinique\">les</span> indications</li></ul>"},"liensGlobaux":[{"href":"https://www.sfed.org/article-abecedaire/classification-tnm-des-adenocarcinomes-coliques/","label":"Classification tnm des adenocarcinomes coliques"},{"href":"https://www.fmcgastro.org/texte-postu/postu-2020-paris/diagnostic-et-surveillance-des-patients-a-tres-haut-risque-genetique-de-ccr/","label":"Diagnostic et surveillance des patients a tres haut risque genetique de ccr"},{"href":"https://www.snfcp.org/questionnaires-outils/cancerologie/cancer-colon-rectum-stade-tnm/","label":"Cancer colon rectum stade tnm"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Cancer colorectal localisé (non métastatique) — Diagnostic histologique (coloscopie + biopsies) et bilan d'extension TDM TAP réalisés ; décision en RCP","detail":"<h4>CAT — cancer colorectal localisé — Choix thérapeutique selon siège (côlon / rectum) et <span class=\"kw-def\">stade</span></h4>","branches":[{"to":"t-endoscopie","label":"Lésion superficielle Tis / T1 superficiel, exérèse R0 endoscopique possible","color":"green"},{"to":"q-colon","label":"Tumeur invasive du côlon (≥ T2)","color":"amber"},{"to":"q-rectum","label":"Tumeur invasive du rectum (≥ T2)","color":"amber"}]},{"id":"t-endoscopie","kind":"terminal","label":"Résection endoscopique","color":"green","detail":"<h4>Indications</h4><ul><li><span class=\"kw-def\">Carcinome in situ (Tis)</span> ou <span class=\"kw-def\">T1</span> à <span class=\"kw-bio\">envahissement</span> sous-muqueux superficiel, limites saines (<span class=\"kw-def\">R0</span>)</li><li>Rectum T1 : <span class=\"kw-ttt\">exérèse locale transanale</span> possible (risque de métastase ganglionnaire ≈ 0)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Polypectomie</span> (pédiculé) ou <span class=\"kw-ttt\">mucosectomie</span> (sessile / plan) ; risques : <span class=\"kw-alerte\">hémorragie</span>, <span class=\"kw-alerte\">perforation</span></li></ul><h4>Suites</h4><ul><li><span class=\"kw-def\">pT1</span> découvert sur la pièce → dossier en <span class=\"kw-def\">RCP</span></li><li>Résection incomplète → nouvelle <span class=\"kw-imagerie\">endoscopie</span>, puis <span class=\"kw-ttt\">chirurgie</span> si non réséquable</li></ul>"},{"id":"q-colon","kind":"decision","label":"Côlon : chirurgie carcinologique première, puis envahissement ganglionnaire (N+) sur la pièce ? — Immuno-nutrition 7 j · pas de néoadjuvant · marges ≥ 5 cm · curage ≥ 12 ganglions","branches":[{"to":"t-colon-chir","label":"N0 (stade I-II)","color":"green"},{"to":"t-adjuvante","label":"N+ (stade III)","color":"amber"}]},{"id":"t-colon-chir","kind":"terminal","label":"Colectomie carcinologique seule","color":"green","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li>Côlon droit : <span class=\"kw-ttt\">hémicolectomie droite</span> + curage (<span class=\"kw-ci\">pas de section à l'origine de l'AMS</span>)</li><li>Côlon gauche : <span class=\"kw-ttt\">colectomie gauche</span> + curage AMI (<span class=\"kw-ttt\">section à l'origine de l'AMI possible</span>)</li><li>Marges <span class=\"kw-chiffre\">≥ 5 cm</span>, curage de <span class=\"kw-chiffre\">≥ 12 ganglions</span></li></ul><h4>Adjuvant</h4><ul><li><span class=\"kw-def\">Stade</span> I : <span class=\"kw-ci\">pas de traitement adjuvant</span> · <span class=\"kw-chiffre\">Stade II</span> : <span class=\"kw-ttt\">chimiothérapie</span> discutée au cas par cas en <span class=\"kw-def\">RCP</span> (selon FR ACP)</li></ul>"},{"id":"t-adjuvante","kind":"terminal","label":"Chirurgie + chimiothérapie adjuvante","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-def\">Stade</span> III post-opératoire = <span class=\"kw-bio\">envahissement</span> ganglionnaire <span class=\"kw-def\">N+</span> sur la pièce</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie adjuvante</span> après colectomie carcinologique</li></ul>"},{"id":"q-rectum","kind":"decision","label":"Rectum : bas / moyen rectum avec marge circonférentielle ≤ 1 mm ou tumeur T4 ? — Siège défini sur l'extrémité inférieure ; IRM pelvienne = marge circonférentielle / fascia recti","branches":[{"to":"t-neoadj","label":"Oui — indication indiscutable de néoadjuvant","color":"amber"},{"to":"t-rectum-chir","label":"Non — haut rectum ou pas d'indication","color":"green"}]},{"id":"t-neoadj","kind":"terminal","label":"Radiochimiothérapie néoadjuvante puis chirurgie","color":"amber","detail":"<h4>Indications</h4><ul><li>Indiscutables : <span class=\"kw-chiffre\">marge circonférentielle ≤ 1 mm</span>, tumeur <span class=\"kw-def\">T4</span></li><li>Relatives : <span class=\"kw-def\">cTN+</span>, ou T2-T3 avec marge circonférentielle petite</li></ul><h4>Objectif</h4><ul><li>Downsizing (réduire la taille) + downstaging pour faciliter l'<span class=\"kw-ttt\">exérèse</span></li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Exérèse totale du mésorectum (TME)</span></li><li>Bas rectum à <span class=\"kw-chiffre\">&lt; 1 cm du sphincter externe</span> → <span class=\"kw-ttt\">amputation abdomino-périnéale</span> + <span class=\"kw-alerte\">colostomie gauche définitive</span></li></ul><h4>Adjuvant</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie adjuvante</span> si <span class=\"kw-def\">stade</span> III post-opératoire (N+)</li></ul>"},{"id":"t-rectum-chir","kind":"terminal","label":"Chirurgie première (résection + mésorectum)","color":"green","detail":"<h4>Haut rectum</h4><ul><li><span class=\"kw-ttt\">Résection partielle du mésorectum</span> + anastomose colorectale <span class=\"kw-chiffre\">5 cm</span> sous le pôle inférieur de la tumeur</li></ul><h4>Moyen / bas rectum (marge <span class=\"kw-chiffre\">> 1 cm</span>)</h4><ul><li><span class=\"kw-ttt\">Exérèse totale du mésorectum</span> + anastomose colo-anale latéro-terminale ou réservoir colique</li></ul><h4>Adjuvant</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie adjuvante</span> si <span class=\"kw-def\">stade</span> III post-opératoire (N+)</li></ul>"}]},"cards":[{"i":"32de198ad498","n":301,"o":"301-1","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","q":"Quels sont les principaux types histologiques d'adénocarcinomes colorectaux et comment est évalué le grade de différenciation de l'adénocarcinome lieberkühnien ?","a":"<p>L'immense majorité des cancers colorectaux sont des <strong>adénocarcinomes</strong>. On distingue :</p><ul><li><strong>ADK lieberkühnien</strong> (forme habituelle).</li><li><strong>ADK colloïde (mucineux)</strong> : avec une production importante de mucus et un pronostic plus défavorable.</li><li><strong>ADK à cellules en bague à chaton</strong> : forme rare et agressive.</li></ul><p>Le grade de différenciation de l'ADK lieberkühnien est évalué par le <strong>pourcentage de glandes coliques dans la tumeur</strong> :</p><ul><li><strong>Grade 1 (bien différencié)</strong> : > 95% de glandes coliques.</li><li><strong>Grade 2 (moyennement différencié)</strong> : 50-95%.</li><li><strong>Grade 3 (peu différencié)</strong> : 5-50%.</li><li><strong>Grade 4 (indifférencié)</strong> : < 5%.</li></ul>"},{"i":"5df831e1af7f","n":301,"o":"301-1","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","q":"Quelle est la définition générale des tumeurs colorectales bénignes et malignes, et lesquelles ont un potentiel de transformation maligne ?","a":"<p>Les tumeurs colorectales se répartissent en tumeurs <strong>bénignes</strong> (polypes) et <strong>malignes</strong> (adénocarcinomes).</p><p>Seuls les <strong>adénomes</strong> et les <strong>lésions festonnées</strong> ont un potentiel de transformation maligne.</p>"},{"i":"5f14a71648a4","n":301,"o":"301-1","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","q":"Concernant les tumeurs colorectales bénignes, quelle est la définition des adénomes et quels sont leurs aspects macroscopiques en endoscopie ?","a":"<p>Les <strong>adénomes</strong> sont des tumeurs bénignes qui se développent à partir des glandes de Lieberkühn de la muqueuse colorectale, et sont considérées par définition comme une <strong>dysplasie</strong>.</p><p>Leurs aspects macroscopiques en endoscopie sont :<ul><li><strong>Polype pédiculé</strong> : lésion exophytique rattachée à la paroi par un pied.</li><li><strong>Polype sessile</strong> : large base d'implantation.</li><li><strong>Lésion plane (adénome plan)</strong> : épaisseur inférieure à ½ du diamètre, considérée comme plus à risque de cancérisation.</li></ul></p>"},{"i":"aeb94671b263","n":301,"o":"301-1","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","q":"Quels sont les principaux sous-types histologiques des adénomes colorectaux selon l'OMS, et quel est leur risque de transformation maligne ?","a":"<p>Selon la classification OMS, les principaux sous-types histologiques des adénomes sont :</p><ul><li><strong>Adénome tubuleux</strong> : 75% des cas, risque de transformation faible.</li><li><strong>Adénome tubulo-villeux</strong> : 20% des cas, risque de transformation intermédiaire.</li><li><strong>Adénome villeux</strong> : 5% des cas, risque de transformation <strong>élevé</strong> (jusqu'à 40%), surtout s'il est volumineux.</li></ul>"},{"i":"d34be7868dcd","n":301,"o":"301-1","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes coliques","q":"Quels sont les trois principaux types de polypes colorectaux bénins qui ne dégénèrent jamais ?","a":"<p>Les trois principaux types de polypes colorectaux bénins sans potentiel de dégénérescence sont :</p><ul><li>Les <strong>polypes hyperplasiques</strong> (très fréquents).</li><li>Les <strong>polypes hamartomateux / juvéniles</strong>.</li><li>Les <strong>pseudo-polypes inflammatoires</strong> (observés sur muqueuse de MICI).</li></ul>"},{"i":"794233f4a505","n":301,"o":"301-12","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les éléments à évaluer lors de l'examen général d'un patient suspect de cancer colorectal ?","a":"<p>L'examen général doit évaluer :</p><ul><li>Le <strong>poids, l'IMC et la courbe pondérale</strong> pour rechercher une <strong>AEG</strong>.</li><li>Le <strong>score OMS/performance status</strong> pour l'évaluation pré-thérapeutique.</li><li>La <strong>pâleur cutanéo-muqueuse</strong>, évocatrice d'anémie.</li><li>La palpation des <strong>aires ganglionnaires</strong>, notamment le <strong>ganglion sus-claviculaire gauche de Troisier</strong>.</li></ul>"},{"i":"b8dfdd1ecf09","n":301,"o":"301-12","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire d'un patient suspect de cancer colorectal ?","a":"<p>Lors de l'interrogatoire, il faut rechercher :</p><ul><li>Des <strong>facteurs de risque personnels</strong> : âge, antécédents de polype, CCR, MICI, acromégalie, ou diabète.</li><li>Des <strong>facteurs de risque familiaux</strong> : CCR ou cancer du spectre de Lynch chez un apparenté au 1<sup>er</sup> ou 2<sup>ème</sup> degré, et l'âge d'atteinte.</li><li>Le <strong>mode de vie</strong> : consommation d'alcool, tabac, alimentation et sédentarité.</li><li>Les <strong>signes fonctionnels</strong> : rectorragies, méléna, troubles du transit récents, douleurs abdominales, et un syndrome d'altération de l'état général (AEG).</li></ul>"},{"i":"b96c1c456525","n":301,"o":"301-12","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les éléments clés de l'examen abdominal et du toucher rectal lors de la recherche d'un cancer colorectal ?","a":"<p>Lors de l'examen abdominal, il faut rechercher :</p><ul><li>À l'inspection, un ballonnement ou des cicatrices.</li><li>À la palpation, une <strong>masse abdominale</strong> (notamment au niveau du côlon droit), une sensibilité localisée.</li><li>La recherche d'<strong>ascite</strong> et de <strong>carcinose péritonéale</strong> (gâteau épiploïque, nodule de Sœur Marie-Joseph ombilical).</li><li>Une <strong>hépatomégalie hétérogène</strong> ou un « foie marronné » évocateur de métastases hépatiques.</li></ul><p>Le toucher rectal systématique (sur rectum vide, en décubitus dorsal ou genu-pectorale) doit évaluer :</p><ul><li>La <strong>distance à la marge anale</strong> et à la <strong>sangle pubo-rectale</strong>.</li><li>La <strong>taille</strong> (2 plus grands diamètres) et l'<strong>aspect</strong> de la lésion (polypoïde sessile/pédiculé, ulcéré, ulcéro-bourgeonnant, infiltrant).</li><li>La <strong>mobilité et la fixation</strong> par rapport aux plans pariétaux profonds (fixation pariétale = risque de résection R2).</li><li>L'<strong>extension circonférentielle</strong>.</li><li>La recherche de <strong>nodules indurés dans le mésorectum</strong>.</li><li>Chez l'homme, l'état de la prostate, et la présence de <strong>sang sur le doigtier</strong> à la sortie.</li></ul>"},{"i":"bed53e673984","n":301,"o":"301-12","u":"Diagnostic positif","t":"Connaître les différentes étapes de l’examen clinique","q":"Quels sont les signes de complications et le syndrome rectal à rechercher chez un patient suspect de cancer colorectal ?","a":"<p>Les signes de complications à rechercher sont :</p><ul><li>Une <strong>occlusion intestinale</strong> : arrêt des matières et des gaz, météorisme, défense en fosse iliaque droite en cas de souffrance cæcale.</li><li>Une <strong>péritonite</strong> : défense ou contracture (attention aux formes asthéniques du sujet âgé).</li><li>Une <strong>infection</strong> : fièvre, frissons (endocardite à <em>Streptococcus gallolyticus</em> notamment).</li></ul><p>Le <strong>syndrome rectal</strong>, sémiologie spécifique du cancer du rectum, inclut :</p><ul><li>Les <strong>épreintes</strong> : douleurs coliques/pelviennes accompagnées d'un spasme rectal, soulagées par l'émission de selles.</li><li>Le <strong>ténesme</strong> : tension douloureuse dans la région anale, persistante après l'exonération.</li><li>Les <strong>faux besoins/impériosité</strong> : émissions de glaires par l'anus.</li></ul>"},{"i":"0ba810c4677d","n":301,"o":"301-13","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention","q":"Quel est le bilan biologique pré-opératoire systématique à réaliser avant la chirurgie d'un cancer colorectal ?","a":"<p>Le bilan biologique pré-opératoire standard comprend :</p><ul><li>une <strong>NFS</strong> (Numération Formule Sanguine) ;</li><li>un <strong>bilan d'hémostase</strong> ;</li><li>un <strong>bilan transfusionnel</strong> ;</li><li>un <strong>bilan nutritionnel</strong> (albumine, pré-albumine, bilan martial) ;</li><li>un <strong>bilan des fonctions d'organes</strong> (bilan rénal, bilan hépatique).</li></ul>"},{"i":"2c2597db2df6","n":301,"o":"301-13","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention","q":"Dans quel contexte et pour quel type de lésion une écho-endoscopie rectale est-elle indiquée ?","a":"<p>L'écho-endoscopie rectale est indiquée pour les <strong>petites tumeurs T1-T2 superficielles</strong> (classification usTNM) du rectum, notamment pour affiner la stadification locale.</p>"},{"i":"9a97485a2f13","n":301,"o":"301-13","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention","q":"Quel est l'examen de première intention pour confirmer le diagnostic positif de cancer colorectal et quel est son gold standard ?","a":"<p>L'examen de première intention pour confirmer le diagnostic positif de cancer colorectal est la <strong>coloscopie totale</strong>. Son gold standard implique une exploration du rectum et de tout le cadre colique <strong>jusqu'à la dernière anse iléale</strong>, associée à des <strong>biopsies multiples</strong> de toute lésion suspecte pour analyse histologique.</p>"},{"i":"c8daab77818e","n":301,"o":"301-13","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention","q":"Quel est l'intérêt du dosage de l'ACE (antigène carcino-embryonnaire) dans la prise en charge d'un cancer colorectal ?","a":"<p>Le dosage de l'ACE est réalisé <strong>uniquement en pré-thérapeutique</strong>, après confirmation histologique du cancer colorectal. Il sert de <strong>valeur de référence pour le suivi</strong> post-thérapeutique de la maladie.</p>"},{"i":"d4b8b832a740","n":301,"o":"301-13","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention","q":"Quels sont les examens complémentaires systématiques du bilan d'extension d'un cancer colorectal ?","a":"<ul><li>Une <strong>TDM thoraco-abdomino-pelvienne (TAP) injectée</strong> est systématique pour évaluer l'extension à distance (poumon, foie, péritoine, ganglions).</li><li>Pour le cancer du rectum, une <strong>IRM pelvienne</strong> est systématique pour mesurer la marge circonférentielle au fascia recti, évaluer le T-stade local et l'envahissement du mésorectum.</li></ul>"},{"i":"2b37abc39242","n":301,"o":"301-4","u":"Définition","t":"Connaître la définition des polypes et des polyposes","q":"Quelles sont les principales formes de polypose familiale et leurs caractéristiques ?","a":"<ul><li><strong>Polypose Adénomateuse Familiale (PAF)</strong> : liée au gène <strong>APC</strong> (transmission autosomique dominante), elle présente <strong>plus de 100 polypes adénomateux</strong>.</li><li><strong>MAP (MYH-associated polyposis)</strong> : liée au gène <strong>MUTYH</strong> (transmission autosomique récessive), elle présente <strong>5 à 100 polypes adénomateux</strong>, souvent plus tardifs.</li><li><strong>Peutz-Jeghers</strong> : liée au gène <strong>LKB1/STK11</strong> (transmission autosomique dominante), elle se caractérise par des <strong>polypes hamartomateux</strong> et une lentiginose péri-orificielle.</li><li><strong>Cowden</strong> : liée au gène <strong>PTEN</strong> (transmission autosomique dominante), elle présente des <strong>hamartomes</strong> (peau, thyroïde, côlon, endomètre).</li><li><strong>Polypose juvénile</strong> : liée aux gènes <strong>SMAD4/BMPR1A</strong> (transmission autosomique dominante), elle est caractérisée par des <strong>hamartomes diffus</strong> du tube digestif.</li></ul>"},{"i":"5b73f2285ece","n":301,"o":"301-4","u":"Définition","t":"Connaître la définition des polypes et des polyposes","q":"Comment distingue-t-on macroscopiquement les polypes en endoscopie ?","a":"<ul><li><strong>Polype pédiculé</strong> : rattaché à la paroi colique par un pied, plus ou moins large, exophytique.</li><li><strong>Polype sessile</strong> : possède une base d'implantation large, avec une épaisseur supérieure à la moitié de son plus grand diamètre.</li><li><strong>Lésion plane (polype plan)</strong> : son épaisseur est inférieure à la moitié de son plus grand diamètre ; ce type de lésion est plus à risque de cancérisation et plus difficile à détecter en coloscopie.</li></ul>"},{"i":"a99b23c21b0e","n":301,"o":"301-4","u":"Définition","t":"Connaître la définition des polypes et des polyposes","q":"Quelle est la définition d'un polype du tube digestif ?","a":"<p>Un polype est une <strong>lésion saillante macroscopique</strong> de la muqueuse à la surface du tube digestif. Sa définition est purement <strong>morphologique</strong> et ne préjuge pas de son type histologique ou de son potentiel évolutif.</p>"},{"i":"fc7ac48aed27","n":301,"o":"301-4","u":"Définition","t":"Connaître la définition des polypes et des polyposes","q":"Quelle est la définition d'une polypose du tube digestif ?","a":"<p>Une polypose est définie par la présence d'un <strong>grand nombre de polypes</strong> synchrones ou métachrones dans le tube digestif. En pratique, on évoque une polypose familiale dès <strong>plus de 10 polypes adénomateux colorectaux</strong>, notamment en présence d'antécédents personnels ou familiaux de cancer colorectal.</p>"},{"i":"04b3e9c31210","n":301,"o":"301-5","u":"Suivi et/ou pronostic","t":"Connaître la filiation adénome cancer","q":"Quelle est la proportion de cancers colorectaux sporadiques qui résultent d'une filiation adénome-cancer ?","a":"<p>La filiation adénome-cancer explique <strong>60 à 80 %</strong> (parfois 60 à 90 %) des cancers colorectaux sporadiques.</p>"},{"i":"4ecdbe96ecde","n":301,"o":"301-5","u":"Suivi et/ou pronostic","t":"Connaître la filiation adénome cancer","q":"Quel est l'événement pivot conceptuel qui détermine la prise en charge thérapeutique d'une lésion colorectale, et quelle en est la conséquence ?","a":"<p>L'événement pivot est le <strong>franchissement de la lame basale</strong>. Si la lame basale n'est pas franchie (lésion intra-épithéliale comme un carcinome in situ), une <strong>résection endoscopique</strong> est suffisante si R0. Si la lame basale est franchie (cancer invasif T1), une discussion en <strong>RCP</strong> est nécessaire, pouvant mener à une résection endoscopique seule pour des T1 superficiels R0, ou à une <strong>chirurgie</strong>.</p>"},{"i":"5842608931c5","n":301,"o":"301-5","u":"Suivi et/ou pronostic","t":"Connaître la filiation adénome cancer","q":"Quels sont les principaux facteurs de cancérisation qui augmentent le risque de transformation maligne d'un adénome colorectal ?","a":"<ul><li>Une <strong>taille de l'adénome supérieure à 1 cm</strong>.</li><li>La présence d'un <strong>contingent villeux supérieur à 25 %</strong>.</li><li>La présence d'une <strong>dysplasie de haut grade</strong> (pTis).</li><li>La découverte d'au moins <strong>trois adénomes synchrones</strong>.</li></ul>"},{"i":"6e289cbabe96","n":301,"o":"301-5","u":"Suivi et/ou pronostic","t":"Connaître la filiation adénome cancer","q":"Quelle est la durée moyenne de la filiation adénome-cancer, du stade de dysplasie de bas grade jusqu'au carcinome in situ ?","a":"<p>La durée moyenne de cette filiation est de <strong>10 à 15 ans</strong> entre une dysplasie de bas grade et le stade de carcinome in situ.</p>"},{"i":"d7c6ec54e62a","n":301,"o":"301-5","u":"Suivi et/ou pronostic","t":"Connaître la filiation adénome cancer","q":"Décrivez la séquence cytologique de la filiation adénome-cancer menant à l'invasion.","a":"<ul><li>Adénome en <strong>dysplasie de bas grade</strong></li><li>Adénome en <strong>dysplasie de haut grade</strong> / <strong>carcinome in situ</strong> (pTis), sans franchissement de la lame basale</li><li><strong>Cancer invasif sous-muqueux</strong> (T1), avec franchissement de la lame basale</li></ul>"},{"i":"006cb72fe133","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quels signes cliniques digestifs liés au transit ou à la douleur doivent faire évoquer un cancer colorectal ?","a":"<ul><li>Des <strong>troubles du transit récents</strong>, tels que <strong>constipation progressive</strong>, <strong>diarrhée</strong>, ou <strong>alternance diarrhée-constipation</strong>.</li><li>Des <strong>douleurs abdominales</strong> de type <strong>coliques</strong>, <strong>pesanteurs</strong> ou <strong>ballonnements</strong>.</li><li>Le syndrome de Koenig, caractérisé par des <strong>crises douloureuses brutales</strong> cédant en débâcle diarrhéique, évocateur d'une <strong>sténose tumorale serrée</strong>.</li></ul>"},{"i":"0340cdb6fdea","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quels sont les signes généraux qui peuvent révéler un cancer colorectal ?","a":"<p>Les signes généraux non spécifiques incluent un <strong>syndrome d'altération de l'état général (AEG)</strong> avec <strong>asthénie</strong>, <strong>anorexie</strong> et <strong>amaigrissement</strong>. Une <strong>anémie ferriprive isolée</strong>, surtout chez un sujet de <strong>plus de 50 ans</strong>, doit systématiquement faire rechercher une cause digestive.</p>"},{"i":"10822708410e","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quels sont les signes révélant un cancer colorectal au stade métastatique ?","a":"<p>La révélation peut se faire par des signes liés aux métastases :</p><ul><li>Une <strong>hépatomégalie hétérogène</strong> ou un « foie marronné » en cas de métastases hépatiques.</li><li>Une <strong>dyspnée</strong> due à des métastases pulmonaires.</li><li>Des <strong>douleurs osseuses</strong> en cas de métastases osseuses.</li><li>Une <strong>carcinose péritonéale</strong> se manifestant par une <strong>ascite</strong> ou un nodule de Sœur Marie-Joseph.</li></ul>"},{"i":"55daf8bf9f52","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quels signes à l'examen clinique peuvent révéler un cancer colorectal de façon directe ou indirecte ?","a":"<ul><li>La palpation d'une <strong>masse abdominale</strong> colique, plus fréquente au <strong>côlon droit</strong>.</li><li>Des signes de <strong>carcinose péritonéale</strong> : <strong>ascite</strong>, <strong>gâteau épiploïque</strong>, <strong>nodule ombilical</strong> (nodule de Sœur Marie-Joseph).</li><li>Une <strong>adénopathie sus-claviculaire gauche</strong> (ganglion de Troisier).</li><li>Un <strong>toucher rectal</strong> peut révéler un cancer du rectum, du sang, ou une carcinose dans le cul-de-sac de Douglas.</li></ul>"},{"i":"a8244d7529ae","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quelles sont les complications aiguës pouvant révéler un cancer colorectal ?","a":"<p>Les complications aiguës révélatrices peuvent être :</p><ul><li>Une <strong>occlusion intestinale</strong>, plus fréquente au niveau du <strong>côlon gauche</strong>.</li><li>Une <strong>perforation</strong> ou une <strong>péritonite</strong>.</li><li>La formation d'une <strong>fistule</strong>.</li><li>Des <strong>infections</strong> à porte d'entrée digestive (ex: endocardite, sigmoïdite, abcès hépatique).</li></ul>"},{"i":"e02e427966ed","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Dans quel contexte le dépistage organisé du cancer colorectal peut-il en être la circonstance de découverte ?","a":"<p>Le cancer colorectal peut être découvert dans le cadre du <strong>dépistage organisé</strong> chez les sujets <strong>asymptomatiques</strong> de <strong>50 à 74 ans</strong>, suite à un test <strong>iFOBT positif</strong>, qui déclenche alors systématiquement une <strong>coloscopie</strong>.</p>"},{"i":"fbe139d7e451","n":301,"o":"301-6","u":"Diagnostic positif","t":"Connaître les circonstances de découverte","q":"Quels types de saignements digestifs peuvent révéler un cancer colorectal et quelle est leur orientation topographique habituelle ?","a":"<ul><li>Les <strong>rectorragies</strong> sont fréquentes et orientent vers une lésion du <strong>côlon gauche</strong>.</li><li>Le <strong>méléna</strong> suggère une lésion plus proximale, dans le <strong>côlon droit</strong>.</li><li>Un <strong>saignement occulte</strong>, révélé par une <strong>anémie ferriprive chronique</strong>, est souvent associé à une lésion du <strong>côlon droit</strong>.</li></ul>"},{"i":"734c95cf2f9a","n":301,"o":"301-9","u":"Étiologies","t":"Épidémiologie analytique : connaître les facteurs de risque","q":"Quels sont les trois niveaux de risque de cancer colorectal (CCR) et à quelle proportion de la population générale correspondent-ils ?","a":"<p>Les trois niveaux de risque de CCR sont :</p><ul><li><strong>Modéré</strong> : 80 % de la population générale.</li><li><strong>Élevé</strong> : 15 % de la population générale.</li><li><strong>Très élevé</strong> : 5 % de la population générale.</li></ul>"},{"i":"8fd1ee6633eb","n":301,"o":"301-9","u":"Étiologies","t":"Épidémiologie analytique : connaître les facteurs de risque","q":"Quels sont les principaux facteurs de risque du cancer colorectal (CCR) sporadique ?","a":"<p>Les principaux facteurs de risque du CCR sporadique incluent :</p><ul><li><strong>Âge > 50 ans</strong> (principal facteur de risque, 90 % des CCR).</li><li><strong>Antécédents personnels</strong> : adénome, polype festonné, CCR.</li><li><strong>MICI</strong> (maladies inflammatoires chroniques de l'intestin).</li><li><strong>Acromégalie</strong>.</li><li><strong>Diabète / insulinorésistance</strong>.</li><li><strong>Mode de vie</strong> : consommation d'alcool et de tabac, surpoids/obésité/sédentarité, consommation de viande rouge et charcuterie, alimentation pauvre en fibres.</li></ul>"},{"i":"c3b5a8345f6c","n":301,"o":"301-9","u":"Étiologies","t":"Épidémiologie analytique : connaître les facteurs de risque","q":"Quelles sont les caractéristiques des formes familiales (< 15 %) de cancer colorectal (CCR) ?","a":"<p>Les formes familiales de CCR se divisent en :</p><ul><li><strong>Formes avec anomalie génétique identifiée</strong> (~5 % des CCR) :<ul><li>Syndrome de Lynch (3-4% des CCR).</li><li>Polyposes familiales (ex: PAF, MAP, Cowden, Peutz-Jeghers, polypose juvénile).</li></ul></li><li><strong>Formes sans anomalie génétique identifiée</strong> (~10 % des CCR) :<ul><li>Antécédents familiaux de CCR ou d'adénome > 1 cm ou villeux au 1er, 2e ou 3e degré.</li></ul></li></ul>"}]};